UPDATE apps SET description_fa = 'UntrackMe once set by default to open Twitter, YouTube and Instagram links will transform them into Nitter, Invidious and Bibliogram links and delegate the action to another app.

It also supports Google Maps links to transform them into OpenStreetMap links or Geo URI.

The app will detect shortened URLs and will display the full URL before visiting the site.

**Lite version:

- When sharing a Twitter, YouTube or Google Maps link just pick up UntrackMe to transform it before sharing it with another app.

**Full version:

- Contains all features of the lite version and it also handle all links to remove tracking parameters. It uses its own app picker that display URLs before visiting them.

What is Nitter:

A free and open source alternative Twitter front-end focused on privacy.
Github project: https://github.com/zedeus/nitter

What is Invidious:

A free and open source alternative front-end to YouTube
Github project: https://github.com/omarroth/invidious

What is Bibliogram:

A free and open source alternative front-end to Instagram
Github project: https://github.com/cloudrac3r/bibliogram', description_fa_source = 'official' WHERE package_name = 'app.fedilab.nitterizemelite' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'یک پیام‌رسان خصوصی. بدون شماره تلفن، بدون ایمیل، بدون حساب کاربری. شما یک جفت کلید هستید که روی دستگاه خودتان ساخته شده است. در مسیر پیش‌فرض، هیچ‌کس، حتی ما، نمی‌تواند گفت‌وگوهایتان را به یک هویت واقعی ربط دهد، و فقط اگر یک نام کاربری عمومی ثبت کنید، دیگران می‌توانند پیدایتان کنند.

به‌طور پیش‌فرض همه‌چیز از راه Tor جابه‌جا می‌شود. محتوا با پروتکل Signal سرتاسری رمزگذاری می‌شود. پیام‌ها از راه رله‌ها جابه‌جا می‌شوند، مهروموم‌شده طوری که هیچ رله‌ای نتواند آن‌ها را بخواند، و در مسیر پیش‌فرض رله‌ها هرگز به نشانی IP شما یا اینکه چه کسی هستید پی نمی‌برند. دفترچه‌ی تلفن شما هرگز بارگذاری نمی‌شود.

امکانات:

* جایی که Tor مسدود است هم کار می‌کند: Kryfo خودش راهی برای دور زدن آن پیدا می‌کند
* تحویل از راه رله‌های Nostr، تا پیام‌ها به گوشی‌ای هم برسند که آفلاین بوده است
* گروه با عکس، فایل، پیام صوتی، پاسخ، واکنش، سنجاق و نظرسنجی
* استیکرهای متحرک که فقط به‌صورت یک نام فرستاده می‌شوند، پس هیچ تصویری از گوشی بیرون نمی‌رود
* جست‌وجو در همه‌ی گفت‌وگوهایتان، با نمایه‌ای درون پایگاه داده‌ی رمزگذاری‌شده
* پیام‌های زمان‌دار: پیام‌هایی که پس از زمانی تعیین‌شده محو می‌شوند
* پایگاه داده‌ی محلی رمزگذاری‌شده و نسخه‌های پشتیبان رمزگذاری‌شده
* قفل برنامه با PIN یا بیومتریک، PIN فریب که یک Kryfo خالی باز می‌کند، و گفت‌وگوهای پنهان پشت PIN جداگانه‌ی خودشان
* پاک‌سازی کامل اضطراری که همه‌چیز را پاک می‌کند، حتی رسانه‌های روی حافظه
* گفت‌وگو با کسی که Kryfo را می‌سازد، اگر بخواهید ناشناس
* پانزده زبان
* بدون آمارگیری و تله‌متری

منبع مالی: نه تبلیغ، نه سرمایه‌گذار. با آنچه دوستدارانش می‌دهند می‌چرخد. حمایت اختیاری و ناشناس است، و همه‌ی امکانات در هر حال یکسان کار می‌کنند.', description_fa_source = 'official' WHERE package_name = 'app.kryfo' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Organic Maps یک برنامه سریع، دقیق و آفلاین نقشه و ناوبری GPS است که برای سفر، پیاده‌روی، ترکینگ و دوچرخه‌سواری مناسب است. مسیرها را برنامه‌ریزی، وارد و ضبط کنید و بدون کاهش باتری یا استفاده از اینترنت، از هدایت روان بهره‌مند شوید. مکان‌ها را کشف کنید و در ماجراجویی‌ها و سفرهای خود در سراسر جهان با امنیت حرکت کنید. این برنامه دانلود نامحدود نقشه و به‌روزرسانی‌های دوهفته‌ای ارائه می‌دهد. مبتنی بر OpenStreetMap، ساخته شده توسط داوطلبان، با اولویت حفظ حریم خصوصی، ۱۰۰٪ آفلاین و ۱۰۰٪ رایگان.

آفلاین: برنامه ۱۰۰٪ آفلاین کار می‌کند — شامل جستجو و ناوبری. شما می‌توانید نقشه را کاوش و هدایت کنید بدون اتصال به اینترنت و در مصرف داده و هزینه رومینگ صرفه‌جویی کنید. همچنین بدون انتقال داده در پس‌زمینه، باتری شما طول عمر بیشتری دارد.

سریع: بزرگ‌نمایی، جستجو و محاسبه مسیر به طور قابل توجهی سریع عمل می‌کنند.

دقیق و به‌روز: نقشه‌ها دارای جزئیات فراوان هستند و هر دو هفته یک‌بار برای بازتاب شرایط واقعی به‌روزرسانی می‌شوند. برخلاف بسیاری از رقبا، شامل برچسب ساختمان‌ها، نیمکت‌ها، مسیرهای پیاده‌روی و سایر اطلاعات مفید هستند.

مبتنی بر OpenStreetMap: OpenStreetMap یک نقشه جهانی به سبک ویکی است که توسط میلیون‌ها داوطلب ساخته و نگهداری می‌شود — محلی‌هایی که مناطق خود را بهتر می‌شناسند. این تلاش جمعی باعث ایجاد نقشه‌های بسیار دقیق می‌شود که اغلب از نقشه‌های تجاری در مناطق کم‌نقشه دقیق‌تر است. Organic Maps هر دو هفته یک‌بار داده‌های خود را از OpenStreetMap به‌روزرسانی می‌کند تا نقشه‌های شما تازه و قابل اعتماد باقی بمانند. اگر چیزی کمبود دارد، می‌توانید آن را به OpenStreetMap اضافه کنید و در بهبود نقشه برای همه کمک کنید.

اولویت حریم خصوصی: ما هیچ داده یا شناسه‌ای جمع‌آوری نمی‌کنیم. این بدان معناست که هیچ ریسک نشت داده و هیچ حواس‌پرتی مانند تبلیغات یا اعلان‌های مزاحم وجود ندارد — فقط تجربه‌ای تمیز و خصوصی از نقشه.

ویژگی‌های مهم

کاوش مکان‌ها: جستجو بر اساس آدرس، نام یا دسته‌بندی، کشف میلیون‌ها نقطه مورد علاقه (POI)، و مشاهده اطلاعات دقیق مانند ساعات باز، مقالات ویکی‌پدیا، دسترسی برای ویلچر و سایر جزئیات مفید.

ناوبری GPS: از مسیرهای صوتی و راهنمای قدم به قدم لذت ببرید. مسیرهای پیاده‌روی، دوچرخه‌سواری، ترکینگ یا رانندگی ایجاد کنید — شامل مسیر بین شهرها، کشورها و چندین نقطه عبور. بهترین مسیرها برای سفرهای مترو و رفت و آمد خود پیدا کنید. از Android Auto پشتیبانی می‌شود.

مسیرهای پیاده‌روی و دوچرخه‌سواری از سراسر جهان: لایه‌های ویژه نقشه را فعال کنید تا مسیرهای محبوب پیاده‌روی و دوچرخه‌سواری در سراسر جهان کشف شود، همه از OpenStreetMap تهیه شده است. بین لایه‌ها جابجا شوید تا مسیرهای رنگی دوچرخه و MTB و مسیرهای رسمی پیاده‌روی را مشاهده کنید.

حمل و نقل عمومی: شماره مسیرهای حمل و نقل عمومی را در ایستگاه‌ها ببینید. برنامه زمان‌بندی و مسیرهای زنده در حال توسعه هستند.

سبک‌های نقشه: لایه‌های نقشه‌ای را انتخاب کنید که با فعالیت شما مطابقت دارد — فضای باز، خطوط کانتور، پیاده‌روی، دوچرخه‌سواری، یا مترو/زیرزمینی.

ضبط مسیر: مسیرها و مکان‌های مورد علاقه خود را ضبط، وارد، صادر و به اشتراک بگذارید. از فرمت‌های KML، KMZ، GPX و GeoJSON پشتیبانی می‌کند.

مقالات ویکی‌پدیا: مقالات ویکی‌پدیا برای مکان‌هایی که در نقشه کشف می‌کنید، جستجو کنید. برای پیدا کردن تمام مکان‌ها با مقالات ویکی‌پدیا، در جستجو “?wiki” را تایپ کنید.

ویرایشگر نقشه: با اضافه کردن مکان‌های از دست رفته یا ویرایش مستقیم نقشه از Organic Maps، به OpenStreetMap کمک کنید.

حالت تاریک: برای مشاهده راحت در شب، به حالت تاریک بروید.

این برنامه را امتحان کنید — ۱۰۰٪ رایگان، بدون تبلیغات، سریع و کاملاً آفلاین است. تجربه ناوبری GPS قابل اعتماد برای پیاده‌روی، دوچرخه‌سواری، ترکینگ و سفر در هر نقطه از جهان را داشته باشید! از تجربه نقشه سریع، قابل اعتماد و خصوصی لذت ببرید و با دیگران به اشتراک بگذارید.

Organic Maps یک پروژه مستقل، مبتنی بر جامعه و متن باز است با صدها مشارکت‌کننده که در توسعه ویژگی‌های جدید، رفع مشکلات، ترجمه و پیشبرد پروژه کمک می‌کنند.

به جامعه در تلگرام بپیوندید: @OrganicMapsPersian
یا راه‌های دیگر حمایت از پروژه را بیاموزید: https://organicmaps.app/contribute/

بازخورد صادقانه و نظرات شما در فروشگاه ما را انگیزه می‌دهد! ما دوست داریم از شما بشنویم. سوالی دارید؟ لطفاً برای جزئیات بیشتر و پرسش‌های متداول به وب‌سایت organicmaps.app مراجعه کنید.', description_fa_source = 'official' WHERE package_name = 'app.organicmaps' AND description_fa IS NULL;
UPDATE apps SET description_fa = '🎵 Sound Center یک پخش‌کننده صوتی متن‌باز و مدرن است که موسیقی محلی، پادکست‌ها و محتوای آنلاین را در یک تجربه یکپارچه و ساده در اختیار شما قرار می‌دهد.

چه بخواهید مجموعه موسیقی خود را مدیریت کنید، چه به پادکست‌های مورد علاقه‌تان گوش دهید یا محتوای صوتی آنلاین را کشف کنید، Sound Center تلاش می‌کند همه‌چیز را در محیطی سریع، روان و کاربرپسند در دسترس شما قرار دهد.

✨ قابلیت‌های فعلی:

🎧 پخش موسیقی محلی:
پخش باکیفیت فایل‌های صوتی ذخیره‌شده روی دستگاه، همراه با مدیریت آسان مجموعه موسیقی شخصی.

🎙️ پخش‌کننده پادکست:
پادکست‌های مورد علاقه خود را در کنار موسیقی‌هایتان به‌سادگی پخش و مدیریت کنید.

🌐 پخش استریم:
استریم‌های صوتی آنلاین را جستجو، پخش و مدیریت کنید.

☁️ پخش‌کننده ابری:
موسیقی‌های بدون DRM موجود در SoundCloud را جستجو و مستقیماً در Sound Center پخش کنید.

🚀 قابلیت‌های در حال توسعه:

🛠️ بهبودهای کیفیت زندگی (QOL):
ابزارها و قابلیت‌های کاربردی بیشتری در راه هستند؛ از جمله جستجوی متن آهنگ، ویرایش تگ‌ها، دانلود، تشخیص آهنگ و امکانات بیشتر برای بهبود تجربه استفاده از برنامه.

💡 Sound Center همچنان در حال توسعه است. در GitHub به ما بپیوندید، در توسعه پروژه مشارکت کنید، مشکلات را گزارش دهید و در مسیر پیشرفت Sound Center همراه ما باشید.', description_fa_source = 'official' WHERE package_name = 'app.soundcenter.player' AND description_fa IS NULL;
