UPDATE apps SET description_fa = 'برنامهٔ Balance پیامک موجودی بانک شما را روی خود گوشی می‌خواند و آخرین موجودی هر بانک پشتیبانی‌شده را — تفکیک‌شده بر اساس شمارهٔ حساب، وقتی بانک آن را ذکر کرده باشد — به‌همراه مجموع کل نشان می‌دهد. بدون حساب کاربری، بدون سرویس ابری، بدون آمارگیری و بدون مجوز اینترنت: تجزیه روی دستگاه خودتان انجام می‌شود و داده‌های مالی‌تان رمزنگاری‌شده همان‌جا می‌مانند.

نسخهٔ فعلی برای کاربران ایران ساخته شده و از بانک‌های ایرانی و قالب پیامک‌های فارسی آن‌ها پشتیبانی می‌کند.

