اگر Balance برایتان مفید است، می‌توانید از توسعهٔ آن حمایت کنید: روش‌های کمک مالی در راهنمای پروژه آمده است — https://github.com/AshkanRafiee/balance#donate', description_fa_source = 'official' WHERE package_name = 'com.ashkanrafiee.balance' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Libre Contacts Backup یک برنامهٔ بومی و آزاد (FLOSS) برای اندروید است که پشتیبان‌گیری از مخاطبین را به‌صورت خصوصی و با اولویت محلی انجام می‌دهد. بدون نیاز به حساب کاربری، بدون ابر، بدون ردیابی — مخاطبین شما هرگز دستگاهتان را ترک نمی‌کنند مگر اینکه خودتان فایل پشتیبان را جابه‌جا کنید.

ویژگی‌ها:
* پشتیبان‌گیری بدون افت کیفیت که سلسله‌مراتب کامل Contact ← RawContact ← Data، از جمله گروه‌های مخاطبین، را حفظ می‌کند
* کتاب تلفن SIM در هر پشتیبان ثبت می‌شود؛ در هنگام بازگردانی، مخاطبان SIM را می‌توان به کارت SIM، به دفترچهٔ آدرس دستگاه، یا هر دو بازگرداند — و در گوشی‌هایی با بیش از یک کارت SIM (از جمله eSIM) انتخاب می‌کنید روی کدام کارت‌ها نوشته شوند؛ در گوشی تک‌SIM به‌طور خودکار همان کارت استفاده می‌شود
* پشتیبان‌گیری محلی زمان‌بندی‌شده در ساعتی که خودتان انتخاب می‌کنید — روزانه، هفتگی در روز هفته‌ای که انتخاب می‌کنید، یا ماهانه در روزی از ماه که انتخاب می‌کنید (اگر ماه کوتاه‌تر از آن روز باشد، در آخرین روز ماه اجرا می‌شود) — بدون نیاز به اتصال اینترنت
* آرشیوهای تک‌فایلی LCB شامل خروجی‌های استاندارد JSON، VCF، CSV و نرمال‌شده
* رمزگذاری اختیاری با گذرواژه بر پایهٔ AES-256-GCM (پشتیبانی‌شده توسط Android Keystore)
* بازگردانی هر مخاطب منبع را به‌درستی یکپارچه می‌کند، بدون ادغام اشتباه افرادی که نام یکسان دارند
* خروجی دستی به فرمت‌های CSV و VCF؛ فایل CSV در Excel و سایر نرم‌افزارهای صفحه‌گسترده باز می‌شود
* نگه‌داری بر پایهٔ عمر — تازه‌ترین پشتیبان‌های هر روز، هفته و ماه را با تعدادی که خودتان انتخاب می‌کنید نگه می‌دارد (برای نمونه ۷ روزانه، ۴ هفتگی، ۳ ماهانه)، تا گذشتهٔ نزدیک پشتیبان‌گیری فشرده بماند و تاریخچهٔ قدیمی‌تر کم‌کم خلوت شود — یا فقط N مجموعهٔ آخر را نگه دارید

برنامهٔ Libre Contacts Backup رایگان و متن‌باز است. اگر برایتان مفید است، می‌توانید توسعهٔ آن را حمایت کنید — روش‌های کمک مالی در بخش Donate راهنمای پروژه آمده است: https://librecontactsbackup.ashkanrafiee.com/#donate', description_fa_source = 'official' WHERE package_name = 'com.ashkanrafiee.librecontactsbackup' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'بارکد اسکنر یک برنامه رایگان و متن‌باز است که به شما امکان می‌دهد بارکدها را بخوانید و ایجاد کنید. این برنامه می‌تواند اطلاعاتی درباره محصولات غذایی، لوازم آرایشی، کتاب‌ها و موسیقی (سی‌دی‌ها، صفحه‌های وینیل و...) جمع‌آوری کند.

فرمت‌های مختلف بارکد که توسط برنامه پشتیبانی می‌شوند:
• بارکدهای دوبعدی: QR کد، دیتا ماتریکس، PDF 417، AZTEC
• بارکدهای یک‌بعدی: EAN 13، EAN 8، UPC A، UPC E، کد 128، کد 93، کد 39، کدبار، ITF

جمع‌آوری اطلاعات درباره محصولات هنگام اسکن:
• محصولات غذایی با Open Food Facts
• لوازم آرایشی با Open Beauty Facts
• محصولات غذایی حیوانات خانگی با Open Pet Food Facts
• کتاب‌ها با Open Library
• سی‌دی‌ها، صفحه‌های وینیل و... با MusicBrainz

ویژگی‌های برنامه:
• فقط کافی است دوربین گوشی خود را به سمت بارکد بگیرید تا بلافاصله اطلاعات مربوط به آن را دریافت کنید. همچنین می‌توانید بارکدها را از طریق تصاویر موجود در گوشی خود اسکن کنید.
• با یک اسکن ساده، کارت‌های ویزیت را بخوانید، مخاطبان جدید اضافه کنید، رویدادهای جدید به تقویم خود اضافه کنید، URL باز کنید یا حتی به وای‌فای متصل شوید.
• بارکد محصولات غذایی را اسکن کنید تا اطلاعاتی درباره ترکیبات آن‌ها از طریق پایگاه‌های داده Open Food Facts و Open Beauty Facts دریافت کنید.
• اطلاعات درباره محصول اسکن‌شده را جستجو کنید، با امکان جستجوی سریع در وب‌سایت‌های مختلف مانند آمازون یا Fnac.
• تمام بارکدهای اسکن‌شده را با ابزار تاریخچه پیگیری کنید.
• بارکدهای خود را ایجاد کنید.
• رابط کاربری را با رنگ‌های مختلف، تم روشن یا تیره سفارشی کنید. رابط کاربری با Material 3 طراحی شده و با Material You سازگار است و به شما امکان می‌دهد رنگ‌ها را بر اساس تصویر پس‌زمینه برای دستگاه‌های دارای اندروید 12 یا بالاتر تنظیم کنید.
• متن‌ها به طور کامل به زبان‌های انگلیسی، عربی، اسپانیایی، فرانسوی، پرتغالی، روسی، آلمانی، ترکی، ایتالیایی، اوکراینی، لهستانی، هلندی، رومانیایی و چینی (ساده و سنتی) ترجمه شده‌اند.

این برنامه به حریم خصوصی شما احترام می‌گذارد. هیچ ردیاب یا ابزار تحلیل داده‌ای ندارد و هیچ اطلاعاتی را جمع‌آوری نمی‌کند.

