UPDATE apps SET description_fa = 'دلتا چت یک پیام‌رسان فوری غیرمتمرکز قابل اعتماد است که استفاده از آن برای دوستان، خانواده، گروه‌ها و سازمان‌ها آسان و سرگرم‌کننده است. دلتا چت توسط یک جامعه متعهد از مشارکت‌کنندگان نرم‌افزار آزاد و متن‌باز (FOSS) توسعه یافته است که به‌طور مشترک چندین بار در سال به بهبودها و ویژگی‌های جدید می‌پردازند و این به‌روزرسانی‌ها را در فروشگاه‌ها و پلتفرم‌های مختلف در سرتاسر جهان منتشر می‌کنند.

ویژگی‌ها به‌طور خلاصه:

• ناشناس. ورود فوری بدون نیاز به شماره تلفن، ایمیل یا سایر داده‌های خصوصی.

• انعطاف‌پذیر. از پروفایل‌های چت متعدد پشتیبانی می‌کند و راه‌اندازی آن بر روی چندین دستگاه آسان است.

