UPDATE apps SET description_fa = 'CryptoSafe اپلیکیشنی کاملاً آفلاین برای رمزنگاری و رمزگشایی متن است. اصلاً از اینترنت استفاده نمی‌کند و همه چیز روی گوشی شما می‌ماند.

امکانات:
• جعبه‌های ناشناس: در جعبه‌های محافظت‌شده با رمز عبور چت کنید، هر جعبه با رمز عبور خودش
