* نمایش ماژول‌های نصب‌شده و قابل به‌روزرسانی
* افزودن کاور، تصاویر، تأیید، وابستگی‌ها و غیره (بر پایه مخزن)
* قابلیت جستجو
* امکان افزودن تا ۵ مخزن

