UPDATE apps SET description_fa = 'Thumb-key یک کیبرد هوشمند و <i>محافظ حریم شخصی</i> است، که به صورت ویژه برای انگشت شصت شما طراحی شده.

این برنامه یک <b>لایه شبکه ای 3 در 3</b> را در اختیار شما میگذارد، و از کشیدن انگشت برای کلمات کمتر رایج استفاده میکند. بسیار ساده برای یادگیری و طراحی شده برای تایپ کردن سریع است.

به جای اتکا به سود محور بودن، حدس زدن کلمات و جملات بعدی شما به شکلی ناقض حریم خصوصی به بهانه دقت، طوری که اکثر کیبردها مثل Gboard یا Swift key انجام میدهد، Thumb-key از <b>کلید های بزرگ با مکان قابل حدس</b> استفاده میکند، تا چشم شما به دنبال مکان کلمات روی کیبرد نباشد.

همچنان که جای کلیدها در حافظه عضلانی شما ذخیره میشود، به مرور شما میتوانید مکان حدودی کلیدهای لمسی را یاد بگیرید، و چشم شما هرگز منقطه ویرایش متن را ترک نخواهد کرد.

این پروژه یک دنبال از  <a href="https://www.exideas.com/ME/">MessagEase Keyboard</a> است که دیگر نگهداری نمیشود (و متن بسته است)، که منبع اصلی الهام آن است.', description_fa_source = 'official' WHERE package_name = 'com.dessalines.thumbkey' AND description_fa IS NULL;
