UPDATE apps SET description_fa = 'نامهٔ کی۹ کارخواه رایانامه‌ای آزاد است که با هر ارائه دهندهٔ رایانامه‌ای کار می کند.

<b>ویژگی‌ها</b>

* پشتیبانی از چند حساب کاربری
* صندوق ورودی یکپارچه
