همواره خوشحال می‌شویم که از توسعه‌دهندگان، طراحان، مستندنویسان، مترجمان، جویندگان مشکل و دوستان جدید استقبال کنیم.', description_fa_source = 'official' WHERE package_name = 'com.fsck.k9' AND description_fa IS NULL;
