UPDATE apps SET description_fa = 'اپ چت AI متن‌باز که صفحات تعاملی می‌سازد، نه فقط متن. Kai 9000 جایگزین رایگان ChatGPT با روح، ضربان، حافظه پایدار و یادگیری تقویتی است — دستیاری که با هر مکالمه رشد می‌کند.

Kai 9000 رابط تعاملی بومی می‌سازد — دکمه، فرم، جدول، نمودار و اپ تمام‌صفحه — درون چت. ماشین‌حساب، آزمون یا لیست کار بخواهید و رابط واقعی و کاربردی دریافت کنید. AI فراتر از متن.

🧠 روح و حافظه — چت‌باتی که شما را می‌شناسد
با نوشتن «روح» شخصیت بدهید. ترجیحات، آموخته‌ها و مسائل شناخته‌شده را بین مکالمات یاد می‌گیرد و تقویت می‌کند. خاطرات مفید به شخصیت دائمی ارتقا می‌یابند. هرچه بیشتر چت کنید، هوشمندتر می‌شود.

💓 ضربان قلب — عامل همیشه فعال
Kai 9000 نمی‌خوابد. کارها، ایمیل و روندها را طبق برنامه بررسی می‌کند حتی بدون چت. بازه، ساعات فعال و مدل را تنظیم کنید. فقط وقتی لازم است اطلاع می‌دهد.

⚡ ۲۴ سرویس — یک اپ، همه مدل‌ها
ChatGPT, Gemini, Claude, DeepSeek, Llama, Mistral, Grok و ۱۷ دیگر. مدل محلی با Ollama یا LM Studio برای استفاده خصوصی. چندین حساب، زنجیره پشتیبان خودکار. سطح رایگان بدون API key.

سرویس‌ها
• OpenAI (GPT-4o, GPT-4, o1, o3)
• Google Gemini (با پیوست فایل)
• Anthropic Claude
• DeepSeek (R1 reasoning)
• xAI Grok
• Mistral, Groq, OpenRouter, NVIDIA
• Together, Hugging Face, Cerebras
• Deep Infra, Fireworks, Venice, MiniMax, Moonshot
• Ollama / LM Studio / هر API سازگار با OpenAI
• سطح رایگان

🛠️ بیش از ۴۰ ابزار — فراتر از چت
ابزارهایی که به دستیار اجازه عمل می‌دهند:
• جستجوی وب — پاسخ بلادرنگ
• ایمیل — بررسی، خواندن، پاسخ، نوشتن
• دستورات Shell — ترمینال روی دستگاه
• زمان‌بندی وظایف — تکراری با cron
• تقویم — ایجاد رویداد از چت
• متن به گفتار — صدای طبیعی
• اعلان‌ها — push هشدار
• موقعیت و زمان
• MCP Servers

🖥️ حالت UI تعاملی
تمام‌صفحه بدون markdown. صفحات لمسی در لحظه ساخته می‌شوند. مثل توسعه‌دهنده اپ شخصی در جیب.

🔒 حریم خصوصی، متن‌باز، بدون تبلیغات
تاریخچه رمزنگاری شده روی دستگاه. بدون تبلیغ، بدون جمع‌آوری داده. API مستقیم به ارائه‌دهنده. کاملاً متن‌باز.

🌍 همه جا کار می‌کند
Android, tablet, Chromebook, desktop. دستیار شما، همیشه در دسترس.

نوشتن، کدنویسی، ترجمه یا مطالعه — Kai 9000 جایگزین رایگان و متن‌باز ChatGPT است که با شما سازگار می‌شود.', description_fa_source = 'official' WHERE package_name = 'com.inspiredandroid.kai' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'یک برنامه تقویت رمز عبور که استحکام رمز عبور شما را ارزیابی و رتبه بندی می کند، زمان کرک را تخمین می زند، و هشدارها و پیشنهادات مفیدی برای رمزهای عبور قوی تر ارائه می دهد.

ویژگی ها:

