UPDATE apps SET description_fa = 'اپلیکیشن Scrambled Exif (تلفظ: <i>اِگ‌</i>زیف) به شما کمک می‌کند پیش از اشتراک‌گذاری تصاویر، متادیتای آن‌ها را حذف کنید.

البته اگر دلتان بخواهد.

اگر دوست ندارید شرکت‌های بزرگ اینترنتی (یا هر شخص دیگری) بفهمند عکس‌های شما کجا گرفته شده‌اند، یادتان نرود قبل از اشتراک‌گذاری، متادیتا را حذف کنید.

برای حذف متادیتای یک تصویر، کافی‌ست آن را مانند همیشه به اشتراک بگذارید و گزینه‌ی <i>Scrambled Exif</i> را انتخاب کنید. چند لحظه بعد، پنجره‌ی اشتراک‌گذاری دوباره ظاهر می‌شود. حالا فقط اپلیکیشنی را انتخاب کنید که در ابتدا قصد داشتید با آن تصویر را ارسال کنید.

و تمام!

<b>دسترسی‌های موردنیاز اندروید:</b>

★ خواندن حافظه‌ی خارجی (READ_EXTERNAL_STORAGE) برای دسترسی به تصاویری که سایر اپلیکیشن‌ها با این اپ به اشتراک می‌گذارند.

<b>کد منبع</b>

★ این اپلیکیشن متن‌باز است. می‌توانید کد آن را از اینجا ببینید (و اگر مایل بودید، در توسعه‌اش مشارکت کنید):

https://gitlab.com/juanitobananas/scrambled-exif

<b>ترجمه‌ها</b>

اگر دوست دارید این اپ را به زبان خودتان ترجمه کنید، می‌توانید از طریق ترجمه‌ی این دو پروژه در Transifex کمک کنید:
https://explore.transifex.com/juanitobananas/scrambled-exif/ و https://explore.transifex.com/juanitobananas/libcommon/.

<b>نکات متفرقه و جالب</b>

★ فرمت jpeg (که دوربین اندروید شما تصاویر را با آن ذخیره می‌کند) از Exif استفاده می‌کند. اگر می‌خواهید درباره‌ی Exif بیشتر بدانید، به ویکی‌پدیا سر بزنید.

★ Scrambled Exif همچنین نام فایل‌ها را هم تغییر می‌دهد (این ویژگی قابل غیرفعال‌سازی است).

★ لطفاً کاملاً به حذف‌شدن داده‌ها اعتماد نکنید. Scrambled Exif کارش را خیلی خوب انجام می‌دهد، اما ممکن است گاهی موفق نباشد. همیشه پیش از اشتراک‌گذاری، یک‌بار دیگر بررسی کنید.

★ این اپ واقعاً اطلاعات Exif را <i>درهم</i> نمی‌ریزد، بلکه آن را حذف می‌کند. پس احتمالاً اسمش خیلی دقیق نیست. ولی من ازش خوشم میاد. آیکونش هم تصویر تخم‌مرغ هم‌زده نیست. پس احتمالاً آیکونش هم چندان منطقی نیست. ولی از اونم خوشم میاد. ضمن این‌که عاشق تخم‌مرغم. پس این اپ نه‌فقط اسم و آیکون «عجیب»ی داره، بلکه درواقع ادای احترام (کاملاً جدی!) من به تخم‌مرغ‌هاست. مخصوصاً <i>huevos fritos</i>. چون عاشقشونم.

★ از اشتراک‌گذاری بی‌دغدغه‌ی عکس‌هاتون لذت ببرید!', description_fa_source = 'official' WHERE package_name = 'com.jarsilio.android.scrambledeggsif' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'تاسکی کارخواهی سبک برای ماستودون، یک کارساز شبکهٔ اجتماعی نرم‌افزار آزاد است.

