UPDATE apps SET description_fa = 'RKNHardering یک برنامه اندرویدی برای تشخیص استفاده از VPN و پروکسی در دستگاه است. روش‌شناسی RKN (سرویس فدرال نظارت بر ارتباطات روسیه) برای شناسایی ابزارهای دور زدن فیلترینگ را پیاده‌سازی می‌کند.

نه ماژول تشخیص مستقل به صورت موازی اجرا می‌شوند و نتیجه نهایی توسط VerdictEngine محاسبه می‌شود:

- GeoIP — بررسی IP عمومی در برابر پایگاه‌های داده GeoIP و ارائه‌دهندگان سیگنال hosting/proxy
- مقایسه IP — مقایسه پاسخ‌های IP چکرهای RU و غیر-RU
- نشانه‌های مستقیم — NetworkCapabilities، تنظیمات پروکسی سیستم، برنامه‌های VPN نصب‌شده
- نشانه‌های غیرمستقیم — رابط‌های شبکه، جدول مسیریابی، DNS، خروجی dumpsys VPN، پروکسی‌های localhost
- سیگنال‌های موقعیت مکانی — MCC/SIM/cell/Wi-Fi و جستجوی BeaconDB
- بررسی Bypass — اسکن localhost برای پروکسی‌های SOCKS5/HTTP، Xray gRPC API، نشت شبکه زیرین
- CDN Pulling — درخواست‌های HTTPS به endpoint های trace برای تعیین IP عمومی
- Call Transport — بررسی دسترسی به STUN و MTProto برای تشخیص تونل‌سازی ترافیک
- نشانه‌های نیتیو — بررسی‌های JNI روی رابط‌ها، مسیرها، ماکرهای hook در /proc/self/maps و root

نتیجه نهایی (تشخیص داده نشد / نیاز به بررسی / تشخیص داده شد) با ترکیب وزن‌دار نتایج ماژول‌ها محاسبه می‌شود.

حداقل نسخه اندروید: 8.0 (API 26).
کد منبع: https://github.com/xtclovver/RKNHardering', description_fa_source = 'official' WHERE package_name = 'com.notcvnt.rknhardering' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'تمرین‌های باشگاه را ثبت کنید، پیشرفت قدرت خود را دنبال کنید و اطلاعات تمرینی‌تان را خصوصی نگه دارید.

Flexify یک ردیاب تمرین سریع و آفلاین برای تمرین قدرتی و کاردیو است. ست‌ها، تکرارها و وزنه‌ها را ثبت کنید، برای حفظ ریتم از زمان‌سنج استراحت استفاده کنید و پس از هر جلسه نمودارهای واضح پیشرفت را ببینید.

گزارش تمرینی بهتری بسازید

• تمرین‌های قدرتی، حرکات، ست‌ها، تکرارها و وزنه را ثبت کنید
• جلسه‌ها و انواع کاردیو را ثبت کنید
• بین ست‌ها از زمان‌سنج استراحت و هشدار استفاده کنید
• سابقه تمرین و پیشرفت قدرت را با نمودارها بررسی کنید
• قابلیت‌ها، تنظیمات و ظاهر روشن یا تیره را با برنامه خود هماهنگ کنید

خصوصی، سریع و آفلاین

Flexify به حساب کاربری یا اتصال اینترنت نیاز ندارد. داده‌های تمرینی روی دستگاه شما باقی می‌ماند، بنابراین می‌توانید هرجا تمرین کنید و جلسه‌ها را ثبت کنید. برنامه متن‌باز است و تبلیغات یا ردیابی ندارد.

چه تازه برنامه باشگاهی را شروع کرده باشید و چه در حال بهبود برنامه فعلی باشید، Flexify یک دفترچه تمرین متمرکز و بدون شلوغی در اختیارتان می‌گذارد.', description_fa_source = 'official' WHERE package_name = 'com.presley.flexify' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'عادت‌هایی را که می‌خواهید کنار بگذارید پیگیری کنید و هر قدم رو به جلو را جشن بگیرید.

Quitter یک ردیاب خصوصی برای ترک عادت است؛ برای افرادی که می‌خواهند سیگار، ویپ، الکل، مواد مخدر، محتوای بزرگسالان، شبکه‌های اجتماعی یا عادت‌های شخصی دیگر را کاهش دهند یا کنار بگذارند. تاریخ شروع را تعیین کنید، نقاط عطف را دنبال کنید، در دفترچه یادداشت بنویسید و پیشرفت روزانه‌تان را همیشه ببینید.

از مسیر ترک خود پشتیبانی کنید

• ۱۳ مسیر آمادهٔ ترک عادت و وابستگی را پیگیری کنید
• برای هر عادتی که می‌خواهید تغییر دهید، ردیاب سفارشی بسازید
• نقاط عطف بهبودی مبتنی بر پژوهش و همراه با منبع را دنبال کنید
• افکار و احساسات روزانه را در یک دفترچهٔ خصوصی ثبت کنید
• یادآوری نقاط عطف و اعلان‌های پیشرفت را دریافت کنید
• رنگ‌ها، پوسته‌ها و قابلیت‌های اختیاری را شخصی‌سازی کنید

خصوصی و آفلاین

Quitter به حساب کاربری یا اتصال اینترنت نیاز ندارد. پیشرفت و نوشته‌های دفترچهٔ شما روی دستگاه خودتان می‌مانند. برنامه متن‌باز است، تبلیغ ندارد و شما را ردیابی نمی‌کند.

نقاط عطف، اطلاعات آموزشی برگرفته از منابعی مانند سازمان‌های بهداشت عمومی و پژوهش‌های داوری‌شده هستند. Quitter جایگزین درمان پزشکی، تشخیص یا توصیهٔ حرفه‌ای نیست. برای دریافت کمک پزشکی یا نگرانی دربارهٔ مصرف مواد، با یک متخصص واجدصلاحیت یا خدمات حمایتی محلی تماس بگیرید.', description_fa_source = 'official' WHERE package_name = 'com.quitter.app' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Simple time tracker به شما کمک میکند تا میزان زمانی را که در طول روز صرف فعالیت های مختلف میکنید اندازه گیری کنید. فعالیت های جدید را با یک لمس ساده آغاز کنید. سوابق و آمار را در طول زمان مشاهده کنید. این برنامه متن باز و رایگان است. بعلاوه دارای امکاناتی مثل: ویجت ها، پشتیبان گیری، اعلان و حالت تاریک است. همچنین از ساعت های دارای سیستم عامل Wear OS پشتیبانی می کند و دارای پیچیدگی است.

• <b>محیط کاربری ساده</b>
این برنامه دارای محیط کابری ساده و مینیمالی است که استفاده از آن را آسان میکند.

• <b>ویجت ها</b>
فعالیت های خود را مستقیم از صفحه اصلی اندازه گیری کنید.

• <b>آفلاین کار می کند و به حریم خصوصی شما احترام میگذارد</b>
برنامه به ساخت حساب یا اتصال به اینترنت احتیاجی ندارد. اطلاعات شما همیشه فقط روی  دستگاه شما نگهداری می شوند. نه توسعه دهنده های برنامه و برنامه های جانبی به این اطلاعات هیچ دسترسی ای ندارند.

• <b>رایگان و متن باز</b>
هیچ تبلیغ، خرید درون برنامه ای یا  مجوز های مزاحم ی در  برنامه وجود ندارد. کد منبع نیز به صورت کامل در دسترس است.', description_fa_source = 'official' WHERE package_name = 'com.razeeman.util.simpletimetracker' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'این برنامه می‌تواند عملکردهایی را از صاحب دستگاه (device owner) واگذار کند. به عبارت دیگر، این برنامه به عنوان یک واسطه عمل می‌کند تا عملکردهایی را از صاحب دستگاه فراخوانی کند.

به طور معمول، این اختیار تنها به یک برنامه می‌تواند واگذار شود، اما Dhizuku به شما امکان می‌دهد تا اختیار کامل مالک دستگاه را به برنامه‌های دیگر واگذار کنید.

راه‌اندازی آن آسان است (مثلاً: Shizuku، کد QR).
برای اطلاعات بیشتر، لطفاً <a href="https://github.com/iamr0s/Dhizuku/discussions/19">آموزش</a> را ببینید.

مثال استفاده: این برنامه زمانی ایده‌آل است که نیاز به پشتیبانی همزمان از دو یا چند مجوز صاحب دستگاه داشته باشید.

به طور خاص، در ژاپن، باید از Aurora Store و Test DPC به طور همزمان روی دستگاهی با برخی قابلیت‌های محدود پشتیبانی کنید.

حتی اگر توسعه‌دهنده برنامه از Dhizuku پشتیبانی نکند، می‌توانید با استفاده از ماژول Dhizuku-API-Xposed پشتیبانی از Dhizuku را به صورت اجباری فعال کنید.', description_fa_source = 'official' WHERE package_name = 'com.rosan.dhizuku' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'از میان شهرها با پرش بگذرید، شهرهایی که از ضرب موسیقی تولید شده‌اند.

اگر به ساختمان‌های زیادی بخورید، خواهید مُرد. پیروزمندانه از سقفی به سقف دیگر بپرید، و اوج‌گرفتن امتیازتان را تماشا کنید.

ده‌ها سطح مختلف برای بازی هست، یا می‌توانید از فایل‌های ام‌پی‌تری خودتان برای ساخت جهان‌های شخصی استفاده کنید.

بدون تبلیغات. بدون خریدهای درون‌برنامه‌ای. فقط موسیقی عالی و لحظات خوش.

هر سطح از مانع‌هایی متناظر با موسیقی پس‌زمینه تشکیل شده‌است. با هر مرتبه بازیِ یک سطح، اندازهٔ مانع‌ها یکسان باقی می‌ماند، اما نمای جهان تغییر می‌کند. هیچ دو نشستی از بازی یک‌شکل نیستند.

از هر بازخوردی در <a href="https://github.com/beat-game/beat-game/discussions">گیت‌هاب</a> استقبال می‌شود.

از توسعهٔ بیشتر در <a href="https://github.com/sponsors/pserwylo>اسپانسرهای گیت‌هاب</a> یا <a href="https://liberapay.com/BeatFeet/">لیبراپی</a> پشتیبانی کنید.', description_fa_source = 'official' WHERE package_name = 'com.serwylo.beatgame' AND description_fa IS NULL;
UPDATE apps SET description_fa = '<p>FTPS Server گوشی یا تبلت شما را به یک سرور FTP امن برای اشتراک خصوصی فایل تبدیل می‌کند. عکس‌ها، ویدیو‌ها و سند‌ها را با رایانه‌ای روی همان Wi-Fi به اشتراک بگذارید، بدون بارگذاری در ابر. شما انتخاب می‌کنید چه کسی وصل شود، کدام پوشه را باز کند، و آیا فقط بتواند فایل را دریافت کند یا آن را هم تغییر دهد.</p>
<p><b>فایل را در شبکه خود به اشتراک بگذارید، نه از راه ابر</b></p>
<p>فایل‌ها روی دستگاه Android شما می‌مانند. دستگاه دیگر از راه شبکه خودتان به این سرور FTP وصل می‌شود، پس نسخه‌ای روی فضای ذخیره شخص دیگری نمی‌ماند.</p>
<ul><li>عکس‌ها، ویدیو‌ها و سند‌ها را از گوشی به PC، یا از PC به گوشی منتقل کنید.</li><li>فایل‌های شخصی و کاری را از فضای ابری شخص ثالث دور نگه دارید.</li><li>در خانه، دفتر، یا روی نقطه اتصالی که خودتان کنترل می‌کنید از آن استفاده کنید. کلاینت باید روی همان شبکه باشد: همان Wi-Fi، یا همان نقطه اتصال یا پیوند اشتراک USB.</li><li>سرور را با صفحه خاموش روشن بگذارید. یک اعلان انتقال‌ها را ادامه می‌دهد.</li></ul>
<p><b>انتخاب کنید چه کسی کدام پوشه را باز کند</b></p>
<p>برای هر شخص یا دستگاه یک ورود جدا بسازید و کارهایی را که آن ورود می‌تواند انجام دهد محدود کنید.</p>
<ul><li>برای هر اتصال یک نام کاربری و گذرواژه بسازید.</li><li>به هر ورود پوشه خودش را بدهید. آن ورود نمی‌تواند بقیه فایل‌های دستگاه شما را ببیند.</li><li>دسترسی کامل بدهید، یا یک ورود فقط‌خواندنی که می‌تواند فایل دریافت کند ولی نمی‌تواند بارگذاری، تغییر نام یا حذف کند.</li><li>وقتی دستگاه دیگر آماده اتصال است، نشانی، پورت و ورود‌ها را کپی یا به اشتراک بگذارید.</li></ul>
<p><b>انتقال رمزنگاری‌شده، نه FTP ساده</b></p>
<p>این یک سرور FTPS است: FTP صریح روی TLS (AUTH TLS). FTP ساده، بدون رمزنگاری، استفاده نمی‌شود. گذرواژه و فایل‌ها هنگام عبور از شبکه رمزنگاری می‌شوند.</p>
<ul><li>ورود به صورت آشکار فرستاده نمی‌شود. انتقال‌ها از FTP روی TLS استفاده می‌کنند.</li><li>اولین اجرا یک گواهی TLS برای شما می‌سازد تا بدون تنظیم اضافه وصل شوید.</li><li>اگر از قبل گواهی دارید، می‌توانید به‌جای آن از همان استفاده کنید.</li><li>اثر انگشت گواهی را که در برنامه دیده می‌شود با اثری که کلاینت نشان می‌دهد مقایسه کنید تا بدانید به همین دستگاه رسیده‌اید.</li><li>نام فایل‌ها به زبان خودتان حفظ می‌شود، از جمله حرف‌هایی که در الفبای انگلیسی نیستند.</li></ul>
<p><b>ببینید سرور چه می‌کند</b></p>
<ul><li>برنامه نشانی و پورت را برای وارد کردن در کلاینت نشان می‌دهد.</li><li>هر ورود با پوشه‌اش فهرست می‌شود و این که دسترسی فقط‌خواندنی است یا کامل.</li><li>وقتی چیزی ناموفق است و باید دلیل را ببینید، یک گزارش فعالیت اتصال را نشان می‌دهد.</li><li>پورت و تعداد کلاینت‌هایی را که هم‌زمان می‌توانند وصل باشند خودتان انتخاب می‌کنید.</li></ul>
<p><b>سرور FTP را در چهار گام شروع کنید</b></p>
<p>1. یک کاربر با نام کاربری و گذرواژه اضافه کنید.<br>2. پوشه‌ای را انتخاب کنید که آن کاربر اجازه باز کردنش را دارد.<br>3. فقط‌خواندنی یا دسترسی کامل را انتخاب کنید.<br>4. روی دستگاه دیگر یک کلاینت FTPS را باز کنید، TLS صریح (AUTH TLS) را روشن کنید و نشانی، پورت و ورود را وارد کنید.</p>
<p><b>کلاینت‌هایی که می‌توانند وصل شوند</b></p>
<p>هر کلاینتی که FTPS صریح را پشتیبانی کند کار می‌کند. نمونه: FileZilla و WinSCP روی Windows، FileZilla روی Linux، Cyberduck یا FileZilla روی Mac، و یک کلاینت FTPS روی گوشی دیگر.</p>
<p><b>کاربردهای معمول</b></p>
<ul><li>فایل‌ها را بین گوشی و لپ‌تاپ روی همان Wi-Fi کپی کنید.</li><li>فایل‌های گوشی را از مدیر فایل رایانه باز کنید.</li><li>وقتی کسی باید فقط فایل دریافت کند و کار دیگری نکند، یک ورود فقط‌خواندنی به او بدهید.</li></ul>
<p><b>این سرور FTP چه نیست</b></p>
<p>فایل‌های شما را نزد توسعه‌دهنده یا یک سرویس ابری بارگذاری نمی‌کند. میزبان عمومی فایل هم نیست. آن را روی شبکه‌ای که به آن اعتماد دارید به کار ببرید، مانند Wi-Fi خانه یا دفتر.</p>
<p>FTPS Server متن‌باز (CC0-1.0) است و آگهی ندارد.</p>', description_fa_source = 'official' WHERE package_name = 'com.siarheikuchuk.ftpsserver' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'آیا هنگام تماشای ویدیو یا گوش دادن به موسیقی روی گوشی اغلب خوابتان می‌برد؟ SleepGuard مطمئن می‌شود که دستگاه شما تمام شب روشن نماند.

در بازه‌ای که خودتان انتخاب می‌کنید، یک دایره کوچک قرمز روی هر چیزی که تماشا می‌کنید ظاهر می‌شود. روی آن ضربه بزنید و پخش مثل قبل ادامه پیدا می‌کند. اگر ظرف چند ثانیه روی آن ضربه نزنید - چون خوابتان برده - SleepGuard صفحه را قفل می‌کند، درست مثل فشار دادن دکمه روشن/خاموش. ویدیوی شما متوقف می‌شود و گوشی‌تان برای باقی شب محافظت می‌شود.

یک حالت صوتی هم برای موسیقی، کتاب صوتی و پادکست وجود دارد: به جای دکمه، SleepGuard مانند یک تایمر خواب ساده کار می‌کند که پخش را پس از بازه انتخابی شما متوقف می‌کند - حتی با صفحه خاموش.

چرا به آن نیاز دارید

* یوتیوب و برنامه‌های دیگر با پخش خودکار: بدون SleepGuard، یک ویدیو ویدیوی بعدی را شروع می‌کند و بعدی و بعدی ... تا صبح. در بدترین حالت باتری خالی می‌شود و زنگ هشدارتان دیگر وقتی به آن نیاز دارید به صدا در نمی‌آید. SleepGuard این زنجیره را به‌محض اینکه دیگر واکنش نشان ندهید قطع می‌کند.

* نتفلیکس، پرایم ویدیو و برنامه‌های پخش دیگر: وسط یک قسمت خوابتان می‌برد و بیدار می‌شوید بدون اینکه بدانید کجا چرت زده‌اید. وقت تلف می‌کنید تا به عقب برگردید و آن نقطه را پیدا کنید - گاهی مجبورید تبلیغ‌های طولانی را بارها ببینید. SleepGuard دقیقاً وقتی واکنش نشان نمی‌دهید صفحه را قفل می‌کند، تا برنامه پخش شما بداند از کجا ادامه دهد.

چگونه کار می‌کند

۱. تنظیم کنید هر چند وقت یک‌بار دکمه بررسی ظاهر شود (مثلاً هر ۵ دقیقه).
۲. تنظیم کنید چند ثانیه برای واکنش وقت دارید تا صفحه قفل شود (مثلاً ۳۰ ثانیه).
۳. انتخاب کنید دکمه در کجای صفحه ظاهر شود.
۴. SleepGuard را شروع کنید و به تماشا ادامه دهید.

امکانات

* دو حالت: ویدیو (دکمه بررسی بیداری روی هر برنامه) و صوتی (تایمر خواب برای موسیقی، کتاب صوتی و پادکست، حتی با صفحه خاموش)
* بازه و زمان واکنش قابل تنظیم
* هشت موقعیت دکمه برای انتخاب
* زمان‌بندی قابل اعتماد حتی در پس‌زمینه (از هشدار سیستم استفاده می‌کند)
* کاملاً رایگان، بدون تبلیغ، بدون ردیابی، بدون حساب کاربری

حریم خصوصی

SleepGuard اصلاً هیچ مجوز اینترنتی ندارد. نمی‌تواند هیچ داده‌ای بفرستد یا دریافت کند. دقیقاً دو کار انجام می‌دهد: نمایش یک دکمه و قفل کردن صفحه. هیچ چیزی جمع‌آوری نمی‌کند.

توضیح مجوزها

* نمایش روی برنامه‌های دیگر: برای نشان دادن دایره قرمز روی ویدیوی شما.
* مدیر دستگاه (فقط قفل صفحه): برای قفل کردن صفحه مانند دکمه روشن/خاموش.
* سرویس پیش‌زمینه و هشدار دقیق: تا دکمه بررسی به‌موقع ظاهر شود.
* نادیده گرفتن بهینه‌سازی باتری: تا دکمه هنگامی که برنامه دیگری در پیش‌زمینه است هم مطمئن کار کند.
* اعلان‌ها (اندروید ۱۳+): برای نمایش اعلان همیشگی «SleepGuard فعال است».

متن‌باز

SleepGuard نرم‌افزار آزاد تحت مجوز GNU General Public License v3 است. کد منبع کامل در دسترس است تا هر کسی بتواند دقیقاً ببیند برنامه چه کاری انجام می‌دهد: https://github.com/OlafDrechsler/SleepGuard

پشتیبانی

SleepGuard رایگان است و رایگان می‌ماند. اگر به شما کمک کرد، می‌توانید با یک کمک مالی داوطلبانه از داخل برنامه از توسعه‌دهنده آن حمایت کنید. عمداً هیچ پاداشی در ازای آن نیست - فقط یک تشکر است.

ایده / نام

ایده این برنامه از یک سیستم ایمنی در قطارها می‌آید. در کابین راننده دکمه‌ای وجود دارد که راننده باید در فواصل منظم آن را فشار دهد، وگرنه قطار به‌طور خودکار متوقف می‌شود. با فشار دادن دکمه، راننده تأیید می‌کند که بیدار است. در زبان عامیانه به این دکمه «کلید مرد مرده» می‌گویند و به همین دلیل نام برنامه هم «SleepGuard - پدال هوشیاری «کلید مرد مرده.', description_fa_source = 'official' WHERE package_name = 'com.sleepguard' AND description_fa IS NULL;
