UPDATE apps SET description_fa = 'Verdetto یک اسکنر رایگان کد QR و بارکد برای Android است، بدون تبلیغات و بدون دکمه‌های جعلی. پیوند را پیش از باز شدن نشان می‌دهد، برای خواندن کدهای آسیب‌دیده ساخته شده و محتوای اسکن‌شده را روی تلفن از نظر نشانه‌های هشدار بررسی می‌کند. هرگز نمی‌گوید چیزی بی‌خطر است: «هشداری یافت نشد» یعنی هیچ‌یک از بررسی‌هایش مطابقت نداشت.

• پیوند را پیش از باز شدن ببینید. نشانی، نام شبکه یا مخاطب پیش از باز شدن هر چیزی نمایش داده می‌شود. نتیجه یک خط است: خطر، احتیاط یا هشداری یافت نشد. پیوند هرگز خودبه‌خود باز نمی‌شود مگر اینکه شما این را روشن کنید، و حتی آن‌وقت هم فقط پس از سه ثانیه برای لغو.

• کدهای پاره، رنگ‌رفته و چروک را می‌خواند. رنگ‌رفته، پاره، کج یا معکوس: فقط نشانه بگیرید؛ به جای اینکه از شما بخواهد ثابت نگه دارید، فریم به فریم به تلاش ادامه می‌دهد. برای فوکوس ضربه بزنید، برای بزرگ‌نمایی دو انگشت را باز کنید، یا یک عکس یا تصویر اشتراک‌گذاری‌شده را اسکن کنید. کدهای QR و شکل‌های کوچکشان، Data Matrix، Aztec، PDF417، MaxiCode، بارکدهای خرده‌فروشی و صنعتی، بسته‌های GS1، کارت‌های پرواز، گواهی‌نامه‌های رانندگی و شماره‌های خودرو را می‌خواند.

• استعلام‌های آنلاین که می‌توانید خاموش کنید. وقتی روشن‌اند، محصول، کتاب، صفحهٔ موسیقی، نشریه یا دستگاه در فایلی کوچک جست‌وجو می‌شود که تلفن شما خودش بارگیری می‌کند و می‌خواند، پس شماره به هیچ پایگاه داده‌ای نمی‌رود. شمارهٔ دارو از یک ثبت ملی، شمارهٔ دستگاهی که فایل نمی‌شناسد و شمارهٔ خودرو به ثبت‌های عمومی خودشان می‌روند. سیاست حریم خصوصی هر درخواستی را که برنامه می‌فرستد و گیرنده‌اش را نام می‌برد.

منابع: fdc.nal.usda.gov، fda.gov، nlm.nih.gov، cpsc.gov، nhtsa.gov، fueleconomy.gov، cima.aemps.es، aifa.gov.it، medicaments.gouv.fr، ec.europa.eu. Verdetto برنامه‌ای دولتی یا سیاسی نیست.

• کدهای خودتان را بسازید. کدی از متن، وب‌سایت، Wi-Fi، مخاطب، رویداد تقویم، ایمیل، شمارهٔ تلفن، SMS، مکان یا کارت خودتان، به‌صورت کد QR یا بارکد، با بررسی ظاهری که پیش از چاپ یا اشتراک‌گذاری، روی همین تلفن خوانده می‌شود.

• تاریخچه‌ای که مال شماست. جستجو، فیلترها، موارد دلخواهی که همیشه می‌مانند، تنظیم مدت نگهداری، و یک جلسهٔ خصوصی که چیزی در تاریخچه ذخیره نمی‌کند. همه را به‌صورت CSV صادر کنید، هرگز همراه با گذرواژه یا رمز ورود، و یک CSV را دوباره وارد کنید.

• ساخته‌شده برای دست. کاشی تنظیمات سریع و دو ابزارک صفحهٔ اصلی، حالت فهرست با خروجی CSV، چیدمان برای چپ‌دست‌ها، خواندن نتایج با صدای بلند، پوسته‌های روشن، تیره و سیاه کامل، و 34 زبان. Android 8 و بالاتر.

• رایگان، بدون تبلیغات، بدون ردیابی از سوی Verdetto. بدون حساب، بدون تحلیل نحوه استفاده در برنامه. فریم‌های دوربین روی تلفن خوانده و دور ریخته می‌شوند. هر بررسی و هر رمزگشایی برای همه رایگان است و به لطف کسانی که از آن استفاده می‌کنند همین‌طور می‌ماند: یک مشارکت مالی اختیاری، یک‌باره یا ماهانه، یک نشان قدردانی و امکانات کوچک اضافه می‌دهد؛ هیچ چیزی که به آن نیاز دارید پشت آن نیست. هرگز اصرار نمی‌کند: بدون درخواست امتیازدهی.

