UPDATE apps SET description_fa = 'آنتناپاد مدیر و پخش‌کننده‌ای برای پادپخش‌هاست که دسترسی آنی به میلیون‌ها پادپخش رایگان و پولی، از پادپخش‌کنندگان مستقل تا ناشران بزرگ مانند بی‌بی‌سی، ان‌پی‌آر و سی‌ان‌ان فراهم می‌کند. خوراک‌ها را به‌راحتی با پایگاه داده پادپخش‌های اپل، پرونده‌های OPML یا نشانی‌های ساده RSS بیفزایید، وارد یا صادر کنید.
اپیزودها را بارگیری، پخش جریانی یا در صف قرار دهید و با سرعت‌های پخش قابل تنظیم، پشتیبانی از فصل‌ها و زمان‌سنج خواب از آن‌ها لذت ببرید.
با کنترل‌های خودکارسازی قدرتمند برای بارگیری اپیزودها (تنظیم زمان، دوره و شبکه‌های وای‌فای) و پاک‌سازی اپیزودها (بر پایه برگزیده‌ها و تنظیمات تأخیر)، در زمان، باتری و داده‌های همراه صرفه‌جویی کنید.

آنتناپاد به‌دست دوست‌داران پادپخش ساخته شده و به تمام معنا آزاد است: نرم‌افزار آزاد، رایگان و بدون تبلیغ.

<b>درون‌ریزی، سازمان‌دهی و پخش</b>
• مدیریت پخش از هرکجا: ابزارک صفحهٔ خانه، آگاهی سامانه و واپایش‌های هدفون و بلوتوث
• افزودن و درون‌ریزی خوراک‌ها از شاخه‌های پادپخش‌های اپل، جی‌پادر، fyyd یا Podcast Index، پرونده‌های OPML و پیوندهای اتم یا RSS
• لذّت از شنیدن به شیوهٔ خودتان با سرعت پخش تنظیم‌پذیر، پشتیبانی از فصل‌ها، به‌خاطر سپردن موقعیت پخش و شمارش معکوس پیشرفتهٔ خوابیدن (لرزش برای بازنشانی، کاهش حجم صدا)
• دسترسی به خوراک‌ها و قسمت‌های حفاظت شده با گذرواژه

<b>پیگیری، هم‌رسانی و قدردانی</b>
• بهترین‌ها را با برگزیدن اپیزودها به‌عنوان دلخواه پیگیری کنید
• اپیزود موردنظر را از تاریخچه پخش یا با جست‌وجوی عنوان‌ها و یادداشت‌ها بیابید
• اپیزودها و خوراک‌ها را با گزینه‌های پیشرفته رسانه‌های اجتماعی، رایانامه، خدمات gPodder.net و برون‌ریزی OPML هم‌رسانی کنید

<b>کنترل سامانه</b>
• بارگیری خودکار را کنترل کنید: خوراک‌ها را برگزینید، شبکه‌های همراه را کنار بگذارید، شبکه‌های وای‌فای خاص را انتخاب کنید، نیاز به شارژ بودن گوشی را تنظیم کنید و زمان یا دوره‌ها را مشخص کنید
• ذخیره‌گاه را با تنظیم شمار اپیزودهای نهان‌شده، پاک‌سازی هوشمند و انتخاب مکان دلخواه مدیریت کنید
• با زمینه روشن و تیره با محیط خود سازگار شوید
• از اشتراک‌هایتان با یکپارچگی gPodder.net و برون‌ریزی OPML پشتیبان بگیرید

<b>به اجتماع آنتناپاد بپیوندید!</b>
آنتناپاد به‌دست داوطلبان در حال توسعه فعال است. شما هم می‌توانید با کدنویسی یا نظر دادن یاری رسانید!

اعضای دوستانه انجمن ما آماده پاسخ به هر پرسش شما هستند. شما را به گفت‌وگو درباره ویژگی‌ها و پادپخش به‌صورت کلی نیز دعوت می‌کنیم.
https://forum.antennapod.org/

آنتناپاد به‌دست داوطلبانی مانند شما در Weblate ترجمه شده است:
https://hosted.weblate.org/engage/antennapod', description_fa_source = 'official' WHERE package_name = 'de.danoeh.antennapod' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'در هر دو جهت افقی و عمودی کار می‌کند، می‌تواند بارکدهای وارونه را بخواند،
از طراحی متریال پیروی می‌کند و همچنین قابلیت ایجاد بارکد را نیز داراست.

از کتابخانهٔ پویش بارکد ZXing ("Zebra Crossing") استفاده می‌کند.
قالب‌های بارکد پشتیبانی‌شده:
AZTEC, CODABAR, CODE 39, CODE 93, CODE 128, RSS 14,
DATA MATRIX, EAN 8, EAN 13, ITF, PDF417, QR CODE,
RSS EXPANDED, Telepen, UPC A, UPC E, UPC EAN EXTENSION.

این کاره متن‌باز است:
https://github.com/markusfisch/BinaryEye', description_fa_source = 'official' WHERE package_name = 'de.markusfisch.android.binaryeye' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'بیت‌کوین‌های تان را همیشه با خود در کیف پولتان داشته باشید. به سرعت با اسکن کردن QR-code پرداخت کنید. به عنوان فروشنده، پرداخت‌ها را با امنیت و سرعت دریافت کنید. Bitcoin Wallet اولین برنامه بیت‌کوین بر روی گوشیهای همراه بود و همچنین به عنوانه امن‌ترین برنامه در نظر گرفته می‌‌شود.

خصوصیات

به هیچگونه ثبت نام و یا سرویس جانبی اینترنتی نیاز ندارید. این کیف پول غیر مترمرکز و نظیر به نظیر (p2p) بوده.
نمایش میزان بیت‌کوین به صورت واحد بیت‌کوین, میلی‌ بیت‌کوین و میکرو بیت‌کوین.
تبدیل ارزش به واحد پولی‌ کشورهای متفاوت.
فرستادن و دریافت بیت‌کوین به صورت NFC ، Qrcode و آدرس بیت‌کوین.
بدون دسترسی‌ به اینترنت همچنان می‌توان بیت‌کوین را از طریق بلوتوث پرداخت کرد.
وقتی‌ پول دریافت می‌کنید برنامه شما را مطلع می‌کند.
استفاده از کیف پول‌های کاغذی (همانند آنهایی که به عنوانه cold storage استفاده می‌‌شود).
ویجت برای نشان دادن موجودی شما.
• امنیت: پشتیبانی از SegWit و فرمت جدید bech32.
• حریم خصوصی: پشتیبانی از Tor از طریق برنامه Orbot که جداگانه مورد استفاده قرار می‌گیرد.

 کمک و همکاری

Bitcoin Wallet به صورت کد باز و مجانی‌ تحت لیسانس: GPLv3
https://www.gnu.org/licenses/gpl-3.0.en.html

کد این برنامه به صورت باز در GitLab قابل دسترسی‌ است.
https://gitlab.com/bitcoin-wallet/bitcoin-wallet

همهٔ ترجمها توسط Transifex مدیریت شده.
https://explore.transifex.com/bitcoin-wallet/bitcoin-wallet/

با ریسک خود استفاده کنید.', description_fa_source = 'official' WHERE package_name = 'de.schildbach.wallet' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'FitoTrack یک نرم‌افزار موبایل برای ثبت و مشاهده تمرینات شما است. چه در حال دویدن، دوچرخه سواری یا پیاده روی باشید، FitoTrack مهم ترین اطلاعات را همراه با نمودارها و آمار دقیق به شما نشان می دهد. منبع باز و کاملاً بدون آگهی است.

امکانات:
* پیگیری تمرینات. نوع ورزشی را که دوست دارید دنبال کنید انتخاب کنید و برای مثال، فقط دویدن، دوچرخه سواری یا پیاده روی را شروع کنید. شما می توانید اطلاعات کلی را دقیقاً در زیر نقشه در صفحه ردیابی مشاهده کنید.
* تمرینات خود را مشاهده کنید. اطلاعات عمومی مانند تاریخ، زمان، مدت زمان، مسافت و سرعت را مشاهده کنید. مسیر خود را روی نقشه ببینید. سطح عملکرد خود را از نمودار سرعت محاسبه کنید.
* متن باز. نه تبلیغاتی وجود دارد و نه ردیابی، و کد منبع باز و تحت مجوز GPLv3 است.', description_fa_source = 'official' WHERE package_name = 'de.tadris.fitness' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'نقشه متن باز OSM را با کمک StreetComplete بهبود دهید!

این برنامه نواقص نقشه را در اطراف شما پیدا می‌کند و آن‌ها را در قالب جُستارهایی روی نقشه نشان می‌دهد. هر یک از این جُستارها را با رفتن به محل و پاسخ‌دادن به یک سوال ساده حل نمایید تا نقشه را روزآمد کنید.

اطلاعاتی که وارد می‌کنید به طور مستقیم بدون نیاز به استفاده از ویرایشگر دیگر در نقشه متن باز OSM اضافه می‌شود.', description_fa_source = 'official' WHERE package_name = 'de.westnordost.streetcomplete' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'از طرف ما علاقمندان به تناسب اندام، به شما علاقمندان دیگر!
سلامتتون رو با برنامه مدیریت ورزش WGER، متحول کنید.

آیا اپلیکیشن موردعلاقه‌تون رو پیدا کردید و دوست دارید برنامه ورزشی مخصوص به خودتون رو درست کنید؟
مهم نیست چه جور ورزشکاری هستید، ما همه در یک چیز مشترکیم: عاشق اینیم که پیشرفت و داده‌های سلامتی‌مون رو دنبال کنیم! 3>

ما شما رو به خاطر اینکه هنوز هم سفر ورزشیتون رو با یک دفترچه کوچک پیش می‌برید قضاوت نمی‌کنیم...
اما خب، سلام به قرن ۲۰ ام!

ما یک اپلیکیشن شمارشگر و گزارش وضعیت سلامت و تناسب اندام ۱۰۰٪ رایگان برای شما ساخته‌ایم
که با خلاصه شدن در مهم‌ترین قابلیت‌ها، زندگی رو براتون ساده می‌کنه.
شروع کنید، به ورزش ادامه بدید و پیشرفتتون رو جشن بگیرید!

WGER یک پروژه متن‌باز است و همه‌چیز درباره این چهار مورد است:

بدن شما

تمرین‌های شما

پیشرفت شما

داده‌های شما

بدن شما:
دیگه نیازی نیست مواد تشکیل‌دهنده خوراکی موردعلاقه‌تون رو گوگل کنید!
وعده‌های غذایی روزانه‌تون رو از بین بیش از ۷۸,۰۰۰ محصول انتخاب کنید و ارزش غذایی آن‌ها رو ببینید. وعده‌ها رو به برنامه غذایی اضافه کنید و در تقویم، یک نمای کلی از رژیم‌تون داشته باشید.

تمرین‌های شما:
شما بهتر می‌دونید چه چیزی برای بدنتون مناسبه.
تمرین‌های شخصی خودتون رو از بین ۲۰۰ حرکت متنوع و در حال افزایش بسازید.
بعدش از "حالت باشگاه" استفاده کنید تا شما رو قدم‭ ‬به قدم در طول تمرین راهنمایی کند، در حالی که با یک کلیک وزن‌هایی که زدید رو ثبت می‌کنید.

پیشرفت شما:
هیچ‌وقت هدف‌هاتون رو فراموش نکنید.
وزن‌تون رو زیر نظر بگیرید و آمار پیشرفت‌تون رو ذخیره کنید.

داده‌های شما:
WGER دفترچه خاطرات ورزشی شخصی‌شده شماست – اما این شما هستید که صاحب داده‌هایتان هستید.
از REST API استفاده کنید و با داده‌هاتون کارهای فوق‌العاده انجام بدید.

یک نکته مهم: این اپ رایگان بر اساس بودجه اضافی نیست و از شما کمک مالی نمی‌خواهیم.
بلکه یک پروژه جامعه‌محور است که دائماً در حال رشد است. پس خودتون رو برای قابلیت‌های جدید هیجان‌زده کنید!

متن‌باز – این یعنی چی؟
یعنی تمام کد این برنامه و سرورش رایگان است و در دسترس همه قرار دارد:

می‌خواهید WGER رو روی سرور خودتون برای باشگاه محل اجرا کنید؟ حله!

یک قابلیت خاص کمه و می‌خواهید خودتون اضافهش کنید؟ از همین امروز شروع کنید!

می‌خواهید مطمئن بشوید که اطلاعاتی جایی فرستاده نمی‌شه؟ می‌توانید بررسی کنید!

به جامعه ما بپیوندید! بخشی از علاقه‌مندان به ورزش و متخصصان فناوری از سراسر جهان شوید.
ما دائماً در حال تنظیم و بهینه‌سازی اپلیکیشن متناسب با نیازهایمون هستیم. عاشق مشارکت و نظرات شما هستیم، پس در هر زمانی خوش آمدید که به ما ملحق شوید و آرزوها و ایده‌هاتون رو با ما در میان بگذارید!

-> کد منبع را در اینجا پیدا کنید: https://github.com/wger-project
-> سوال بپرسید یا فقط سلامی بکنید، سرور دیسکورد ما: https://discord.gg/rPWFv6W', description_fa_source = 'official' WHERE package_name = 'de.wger.flutter' AND description_fa IS NULL;
UPDATE apps SET description_fa = '<i>اِیوْز</i> می تواند انواع تصاویر و ویدیوها، از جمله JPEG ها و MP4 های عادی شما را مدیریت کند، اما همچنین چیزهای عجیب و غریب تری مانند <b> TIFF های چند صفحه ای، SVG ها، AVI های قدیمی و بیشتر</b>! این مجموعه رسانه های شما را بررسی می کند تا پرونده های <b>تصویر متحرک</b>، <b>پانوراما</b> (معروف به تصاویر کروی)، <b>360° ویدیو ها</b>، و همچنین <b>geoTIFF</b> را شناسایی کند.

<b>پیمایش و جستجو</b>یک بخش مهم از <i>اِیوْز</i> است. هدف این است که کاربران به راحتی از آلبوم ها به عکس ها به برچسب ها به نقشه ها و غیره دست پیدا کنند.

<i>اِیوْز</i> با اندروید سازگار است (شامل تلوزیون اندرویدی) با قابلیت هایی مانند <b>ابزارک ها</b>, <b>میانبر ها</b>, <b>ذخیره نیرو</b> و <b>جستجو عمومی</b> و همچنین میتوان از آن به عنوان <b>نمایشگر و انتخابگر رسانه</b> استفاده کرد.', description_fa_source = 'official' WHERE package_name = 'deckers.thibault.aves.libre' AND description_fa IS NULL;
UPDATE apps SET description_fa = '<p> Amarok یک برنامه اندرویدی است که به شما امکان می دهد فایل ها و برنامه های خصوصی خود را تنها با یک کلیک مخفی کنید.</p><p> اغلب، ما برای محافظت از فایل‌ها و برنامه‌های خود به رمزنگارهای پیچیده متوسل می‌شویم تا از آنها در برابر چشمان کنجکاو محافظت کنیم. این رمزگذارها، در حالی که موثر هستند، معمولا آهسته و پرمخاطب هستند و رمزگذاری فایل‌های بزرگ مانند ویدیوها و موسیقی را به یک کار دلهره‌آور تبدیل می‌کنند. علیرغم امنیت قوی، این روش‌ها اغلب برای کاربران معمولی که به سادگی می‌خواهند فایل‌ها و برنامه‌های خصوصی خود را از دسترس ناخواسته دور نگه دارند، بسیار زیاد است.</p><p> آماروک به گونه ای طراحی شده است که یک مخفی کننده سبک وزن باشد. این نام فایل ها و هدرها را پنهان می کند و باعث می شود که آنها "فاسد" و غیرقابل باز شدن به نظر برسند. Amarok همچنین برنامه ها را غیرفعال می کند و آنها را در منوی راه اندازی و سیستم نامرئی می کند.</p><p><b>امکانات</b></p><ul> <li><strong>کاربر پسند</strong>: به راحتی فایل‌ها و برنامه‌ها را با یک کلیک پنهان کنید.</li> <li><strong>پنهان‌سازی سریع و کارآمد فایل‌های بزرگ</strong>: با تغییر فقط نام و امضای فایل، بدون تأثیرپذیری از اندازه فایل، آن را پنهان می‌کند.</li> <li><strong>پنهان‌سازی برنامه بدون روت</strong>: برنامه‌ها را از لانچر ناپدید می‌کند. سازگار با حالت‌های Root، Shizuku، Dhizuku، و DSM.</li> <li><strong>دکمه اضطراری</strong>: از یک دکمه شناور برای مخفی کردن سریع برنامه‌ها و فایل‌ها در شرایط اضطراری استفاده کنید. </li> <li><strong> تنظیمات سریع</strong>: یک دکمه در مرکز کنترل برای مخفی کردن فوری، بدون نیاز به اجرای برنامه.</li> <li><strong>قفل برنامه</strong>: دسترسی به Amarok را با یک رمز عبور یا اثر انگشت امن کنید.</li> <li><strong>رابط کاربری دلپذیر</strong>: طراحی تمیز Material3.</li></ul><p>لطفاً توجه داشته باشید که Amarok یک <b>نرم‌افزار رمزگذاری نیست</b>، بلکه ابزاری برای مخفی کردن است. <b>ما به شدت توصیه می‌کنیم از Amarok برای محافظت از فایل‌ها و برنامه‌های محرمانه استفاده نکنید.</b></p>', description_fa_source = 'official' WHERE package_name = 'deltazero.amarok.foss' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'DNSNet به شما این امکان را می دهد که کنترل بیشتری بر ترافیک اینترنتی که از دستگاه شما وارد و خارج می شود داشته باشید. می توانید فایل های host را دانلود کنید تا مجموعه ای از سرویس های تبلیغاتی یا خطر ناک شناخته شده را مسدود کنید و سپس برکناری هایی را در جایی که مناسب می دانید ایجاد کنید.

این سرویس با ایجاد یک تانل VPN سبک وزن که ترافیک اینترنت شما را هنگام استفاده از دستگاه خود فیلتر می کند، کار می کند. اگر زمانی در اتصال به یک سایت یا استفاده از یک برنامه مشکل داشتید، همیشه می توانید یک برنامه را از فیلتر کردن بر کنار کنید یا برای اسم host خاصی استثنا قائل شوید.', description_fa_source = 'official' WHERE package_name = 'dev.clombardo.dnsnet' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'تماس‌ها، پیامک‌ها و اعلان‌های ناخواسته را بدون جایگزینی برنامه پیش‌فرض تماس/پیامک شما مسدود می‌کند.

غربالگری اعلان‌ها (Notification Screening) قواعد مسدودسازی شما را برای RCS، Signal، WhatsApp، ایمیل و هر برنامه پیام‌رسان دیگری که اعلان نشان می‌دهد اعمال می‌کند، نه فقط برنامه پیامک پیش‌فرض شما، تا هرزنامه بدون توجه به اینکه از کدام برنامه می‌رسد فیلتر شود. هشدارها (Alerts) یک هشدار سبک صدا/لرزش/چراغ‌قوه/بیدار کردن صفحه برای اعلان‌های غربالگری‌شده و مجاز ارائه می‌دهند، به‌جای یک اعلان کامل تکراری.

فیلترها:

۱. قاعده عبارت باقاعده برای شماره و محتوای پیامک.
۲. مخاطب
۳. تأیید STIR
۴. تماس تکراری
۵. شماره شماره‌گیری‌شده
۶. برنامه‌های اخیراً استفاده‌شده
۷. زمان‌بندی

جزئیات: https://github.com/KerballOne/SpamBlocker-Extended', description_fa_source = 'official' WHERE package_name = 'dev.kerballone.spamblocker' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Test your reasoning power on a challenging puzzle game where you have to solve a minefield without exploding any mine.
This is a minimalist and modern version of the classic Minesweeper.

Are you able to clear a minefield? Let’s go!

OBJECTIVE
It''s like Minesweeper. You win the game when you''ve flagged every mine in the minefield. Be careful not to trigger one!

NO GUESSING
This game has an algorithm that always creates solvable minefields. You won''t have to guess where the last mine is!

GAME LEVELS
Just like Minesweeper, this game has different levels: Beginner, Intermediate, and Expert. But it also has a unique progressive mode that gets harder when you win.

CUSTOM LEVEL
If the standard modes aren''t enough, you can create your level difficulty!

THEMES
Antimine has more than 15 themes (including light, dark, and AMOLED). And soon more will be added!

MINIMALIST
Clean look and feel: a minimalist visual and also lightweight app size (less than 9MB).

TUTORIAL
Don''t you know how to play Minesweeper? No problem, you can play our tutorial level and enable Tips on settings.

STATISTICS
Check your results and development.

GAME ASSISTANT
The game will automatically flag the squares you isolated. 

CUSTOMIZATION
You can change the game to make it like you want to. 
Example: Help, animations, haptic feedback, question mark.

CONTROLS
It supports four different control schemes. Example: flag using tap or long press.

ACHIEVEMENTS AND LEADERBOARDS 
You have eight achievements to unlock and different leaderboards to share with your friends.

ONLINE OR OFFLINE
You don''t need to be online to play the game!

AUTO-SAVE
You can start a game and continue it later! It will auto-save your game.

Enjoy.', description_fa_source = 'official' WHERE package_name = 'dev.lucanlm.antimine' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'شریک یک راه حل متن باز و کراس پلتفرم، برای انتقال فایل از طریق وای فای یا نقطه اتصال موبایل می باشد.

با شریک شما میتوانید به راحتی تصاویر، برنامه ها، فایل ها، متن و... را به راحتی به هر دستگاهی که به شبکه یکسان متصل است ارسال کنید. راحت و سریع.

پس از انتخاب زبان و مرور مقدمه ، می توانید دکمه های اشتراک و آخرین فایل هایی را که به اشتراک گذاشته اید در صفحه اصلی مشاهده کنید. می توانید تصاویر ، پرونده ها ، برنامه های نصب شده یا متن را به اشتراک بگذارید. پس از انتخاب فایل ، صفحه اشتراک گذاری به شما نشان داده می شود. در اینجا می توانید وضعیت اتصال خود (وای فای / نقطه اتصال تلفن همراه) و لینک مورد نیاز برای باز کردن در دستگاه دیگر را مشاهده کنید. پس از وارد کردن این لینک در مرورگر روی دستگاه دیگر ، بارگیری پرونده شروع می شود. لطفاً اطمینان حاصل کنید که هر دو دستگاه به یک شبکه متصل هستند.

اگر شریک را روی هر دو دستگاه نصب کرده اید، می توانید پس از ارسال فایل روی دکمه "دریافت" در پنل پایین شریک دیگر کلیک کنید. پس از کلیک ، صفحه گیرنده نشان داده می شود. اگر شریک ببیند دستگاه دیگری در شبکه محلی شما چیزی را به اشتراک می گذارد ، نمایش داده می شود. بنابراین می توانید فقط روی آن کلیک کنید ، مرورگر باز می شود و بارگیری شروع می شود.

استفاده از شریک کاملاً رایگان است و هیچ تبلیغی ندارد. علاوه بر این ، کد منبع آن در گیت هاب منتشر شده است ، بنابراین همه می توانند به روند توسعه کمک کنند. اگر آن را پسندیدید ، لطفاً یک ستاره در مخزن گیت هاب ما بگذارید و در نظر بگیرید که سهمی را در اختیار داشته باشید: یک زبان جدید اضافه کنید یا به ما در زمینه کد کمک کنید.

شریک توسط Flutterساخته شده و تحت مجور آزاد (MIT) می باشد.

