UPDATE apps SET description_fa = '<b>وب را دست به دست کن!</b> سِنو اولین مرورگر وب در جهان است که عملکردش با هر نصبِ تازه، بهتر می‌شود. این مرورگر در عین فراهم آوردن تجربه‌ای عادی از وب‌گردی، بر پایه‌ی فناوری همتا‌به‌همتا (P2P) عمل می‌کند تا وب‌سایت‌ها را بین تمام کاربران دست به دست کند.
سِنو همچنین می‌تواند برای دور زدن محدودیت‌های شبکه و دسترسی به محتوا در زمان قطعی اینترنت استفاده شود.

سِنو یک مرورگر کاملا رایگان و متن‌باز است که نیازی به ثبت‌نام ندارد. این مرورگر کاملا بدون تبلیغات است.

ما برخی داده‌های آماری ناشناس مربوط به برنامه و شبکه را جمع‌آوری می‌کنیم. هیچ اطلاعات شخصی‌ای جمع‌آوری نمی‌شود و این داده‌ها هرگز با اشخاص ثالث به اشتراک گذاشته نمی‌شوند. جمع‌آوری این داده‌ها به‌صورت پیش‌فرض فعال است، اما کاربران می‌توانند در هر زمان با مراجعه به <code>تنظیمات ← آمار پس‌زمینه ← آمار سنو</code> آن را غیرفعال کنند. برای اطلاعات بیش‌تر درباره‌ی داده‌هایی که جمع‌آوری می‌کنیم، لطفا <a href="https://ceno.app/privacy-policy/">سیاست حفظ حریم خصوصی</a> را ببینید.

🔓👀 با سِنو به رسانه‌های فیلترشده و دیگر وب‌سایت‌ها دسترسی پیدا کنید. در حالت شخصی، این دسترسی رایگان و ناشناس است.

🚫🌴 در صورت قطع اینترنت در کشور، همچنان می‌توانید به‌کمک سِنو اخبار را بخوانید و در ارتباط بمانید.

