*** سلب مسئولیت ***
پروژه پشتیبان، برنامه‌ها را آن‌طور که شما انتظار دارید تا محافظ امنیت و ناشناس‌بودن شما باشند می‌کند. پیمان‌نامه‌هایی که ما استفاده می‌کنیم، به‌طور گسترده‌ای به‌عنوان موقعیت هنرمندانه در فن‌آوری امنیت شناخته می‌شوند. تا زمانی‌که ما به‌طور مداوم نرم‌افزارهای خود را در جهت نبرد با آخرین تهدیدها و رفع اشتباه‌ها به‌روز می‌کنیم، هیچ فن‌آوری 100% بدون خطا نیست. برای بیشترین حد امنیت و داشتن کاربران ناشناس باید بهترین تلاش را برای ایمن‌نگه‌داشتن آن‌ها به کار برید. PixelKnot هنوز یک ابزار تجربی است و نباید برای استقرار در دنیای واقعی استفاده شود. شما می‌توانید در این‌جا برای این موضوع‌ها راهنمای مقدماتی بیابید https://securityinabox.org', description_fa_source = 'official' WHERE package_name = 'info.guardianproject.pixelknot' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'ریپل دکمهٔ هراسی است که می‌تواند پیام شلّیکش را به هر کاره‌ای که به هراس پاسخ می‌دهد بفستد.  چنین کاره‌هایی می‌توانند کارهایی چون قفل شدن، پنهان کردن خودشان، حذف داده‌های خصوصی، فرستادن پیام اضطراری و نظایر آن را انجام دهند.  این کاره مناسب شرایطیست که زمان برای واکنش وجود دارد، ولی کاربران باید مطمئن شوند که به اشتباه خاموش نشده است.

این نگارشی بتا از کاره است!  اکنون در حال کار برای پشتیبانی هر چه بیش‌تر کاره‌ها هستیم.  ChatSecure، Orweb، Umbrella و Zom در ال حاضر پشتیبانی می‌کنند و این کاره‌ها نیز به زودی خواهند آمد: Courier، PanicButton، OpenKeychain، Orfox، SMSSecure، StoryMaker.

دو سناریوی احتمالی:

* سازمانی به طور مرتّب از سوی نیروهای امنیتی مورد حمله قرار گرفته و تمامی رایانه‌ها و افزاره‌های همراه را زیر و رو می‌کنند. سازمان معمولاً یکی دو دقیقه پیش از آغاز حمله آگاه می‌شود. نیاز به روشی قابل اتّکا برای زدودن تمامی داده‌هایشان از کاره‌های حسّاس است.

* یک کمک‌رسان اجتماعی، مقدار زیادی دادهٔ حسّاس دربارهٔ افراد روی افزاره‌اش داشته و به طور مرتّب آن‌ها را با یک پایگاه دادهٔ امن مرکزی همگام‌سازی می‌کند.  این کمک‌رسان باید در مدّت کوتاهی کشور را ترک کند.  ولی نگهبانان مرزی به طور مرتّب محتوای کامل افزاره‌های همراه افرادی که رد می‌شوند را بارگیری می‌کنند. هنگام انتظار در صف مرزی، کمک‌رسان متوجّه تجاوز به افزاره‌های افراد شده و ناکهان به یاد داده‌های روی افزاره‌اش می‌افتد؛ پس قفل تلفن را گشوده و ماشهٔ پاک‌سازی را که تمامی کاره‌های حسّاس را از افزاره پاک می کند می‌کشد. هنگام بازگشت کمک‌رسان به دفتر مرکزی،‌افزاره دوباره با پایگاه دادهٔ مرکزی هم‌گتم می‌شود.

