UPDATE apps SET description_fa = 'Tower Collector به شما این امکان را می‌دهد که با آپلود مکان‌های GPS دکل‌های سلولی GSM/UMTS/LTE/CDMA/TD-SCDMA/5G (NR) از منطقه خود، در پروژه‌های OpenCellID.org، BeaconDB و @t0stbrot مشارکت کنید. این اندازه‌گیری‌ها به ترسیم نقشه وسعت پوشش شبکه تلفن همراه کمک می‌کنند. می‌توانید از این برنامه برای جمع‌آوری داده‌ها برای اهداف شخصی و استخراج آنها به فایل‌های مختلف استفاده کنید.

برخی از ویژگی‌ها:
• پارامترهای GPS بهینه‌سازی‌شده ویژه برای کاهش تخلیه باتری
• آپلود در پروژه‌های OpenCellID.org، BeaconDB و @t0stbrot
• استخراج به کارت SD به صورت CSV، JSON، GPX، KML و KMZ.
• بدون تبلیغات، برای همیشه!

هدف پروژه OpenCellID.org ایجاد یک پایگاه داده متن‌باز جهانی از مکان‌های سلولی تلفن همراه است. Tower Collector به شما این امکان را می‌دهد که با آپلود مکان‌های دکل‌های سلولی از منطقه خود، در پروژه OpenCellID مشارکت کنید. داده‌های جمع‌آوری‌شده می‌توانند برای مکان‌یابی سریع دستگاه‌ها بدون فعال کردن GPS استفاده شوند.

BeaconDB یک پایگاه داده عمومی است که اطلاعات مکانی مربوط به زیرساخت‌های بی‌سیم رایج (دکل‌های سلولی، نقاط دسترسی WiFi، بیکن‌های بلوتوث) را جمع‌آوری می‌کند. داده‌های دکل‌های سلولی که شما ارائه می‌دهید، جمع‌آوری و تحت مجوز ""Creative Commons (CC-0)"" در اختیار عموم قرار می‌گیرد.

@t0stbrot یک پایگاه داده عمومی است که مکان دکل‌های سلولی را جمع‌آوری می‌کند. داده‌های دکل‌های سلولی که شما ارائه می‌دهید، جمع‌آوری و تحت مجوز ""Creative Commons Attribution-ShareAlike 4.0 (CC BY-SA 4.0)"" در اختیار عموم قرار می‌گیرد.

لطفاً در ترجمه آن به زبان‌های دیگر به من کمک کنید، به https://i18n.zamojski.ovh/ مراجعه کنید.

این برنامه هیچ اطلاعاتی را که بتواند برای شناسایی مستقیم کاربر، دستگاه مورد استفاده یا هرگونه اطلاعات شخصی دیگر استفاده شود، جمع‌آوری، ذخیره یا ارسال نمی‌کند.

لطفاً گزارش اشکالات و درخواست ویژگی را از طریق ایمیل یا مشکلات گیت‌هاب ارسال کنید.', description_fa_source = 'official' WHERE package_name = 'info.zamojski.soft.towercollector' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'به افراد در کشورهای تحت سانسور کمک کنید تا به اینترنت آزاد دسترسی داشته باشند.

دانه برف (Snowflake) چیست؟

دانه برف (Snowflake) به افراد اجازه می دهد تا به شبکه Tor در مکان هایی که مسدود می باشد از طریق پراکسی های داوطلب در کشورهای دیگر دسترسی داشته باشند.

مانند عملکرد وی پی ان که به کاربران اجازه می دهد تا سانسور اینترنتی را دور بزنند، دانه برف (Snowflake) فعالیت اینترنتی شما را به شکل تماس تلفنی یا صوتی نشان می دهد،تا کمتر در نگاه سانسورچی ها قرار بگیرند.

دانه برف (Snowflake) به چه شیوه ای کار میکند؟

دانه برف (Snowflake) از یک فناوری به نام WebRTC استفاده میکند، که به طور رایج توسط نرم افزارهای ویدیو کنفرانس استفاده می شود. این استفاده کاربر از تور (Tor) را از نگاه سانسورچی پنهان میکند تا اینطور به نظر برسد شما در حال تماس صوتی یا تصویری هستید.

برای مطالعه بیشتر به https://snowflake.torproject.org مراجعه کنید

آیا برای من خطری ایجاد می کند؟

نیازی به نگرانی در خصوص اینکه کاربران به چه سایت هایی از طریق برنامه شما مراجعه می کنند نیست. نشانی IP آنها گره خروجی Tor خواهد بود، نه نشانی IP شما (چون شما نقطه ورودی) هستید.

آیا من می توانم از طریق این برنامه سانسور را دور بزنم؟

خیر. برای دور زدن سانسور، شما باید از یک برنامه بر پایه Tor مانند مرورگر Tor یا Orbot استفاده کنید و از طریق تنظیمات برنامه Snowflake را انتخاب کنید.', description_fa_source = 'official' WHERE package_name = 'io.bloco.snowflake' AND description_fa IS NULL;
