* بیست‌ویک — نزدیک‌تر از دیلر به ۲۱؛ مسابقه‌ی ده‌دستی بدون شرط‌بندی
* بیلیارد — توپ‌های دسته‌ات و بعد توپ ۸ را بینداز، با فیزیک واقعی میز، با ربات در سه سطح یا دو نفره
* اسنوکر — یک سرخ، یک رنگی و آخر رنگی‌ها به ترتیب، با ۶، ۱۰ یا ۱۵ سرخ، با ربات در سه سطح یا دو نفره
* راه‌بندان — ماشین‌ها را کنار بزن و ماشینت را از پارکینگ بیرون ببر؛ هر کشیدن یک حرکت، مرحله‌های بی‌پایان
* واکنش زنجیره‌ای — گوی بگذار تا خانه‌ها بترکند و زنجیروار پخش شوند؛ ۲ تا ۴ نفر روی یک گوشی یا با ربات
* منچ — تاس بریز، با شش بیرون بیا، حریف را بزن و مهره‌هایت را به خانه برسان؛ ۲ تا ۴ نفر یا با ربات

بیرون از بازی‌ها:

* چالش روزانه که برای همه‌ی دستگاه‌ها یکسان است، بدون هیچ سروری
* لیگ هفتگی آفلاین با پنج رده
* بیش از هشتاد دستاورد
* آمار و پروفایل
* رابط فارسی، انگلیسی، چینی ساده‌شده، آلمانی و اسپانیایی با تم روشن و تاریک

درباره‌ی حریم خصوصی:

* تنها مجوز اپ لرزش است. حتی مجوز اینترنت هم اعلام نشده
* هیچ تبلیغ، خرید درون‌برنامه‌ای، تحلیل‌گر یا ردیابی وجود ندارد
* همه‌ی دارایی‌ها داخل بسته‌اند. حتی صداها با WebAudio ساخته می‌شوند و یک فایل صوتی هم در بسته نیست
* پیشرفت فقط روی خود دستگاه ذخیره می‌شود و بکاپ خودکار گوگل خاموش است

رایگان و متن‌باز با مجوز MIT.', description_fa_source = 'official' WHERE package_name = 'io.github.choganhq.chogan' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'TunnelForge یک کلاینت VPN اندروید برای شبکه‌هایی است که هنوز از L2TP/IPsec با IKEv1 استفاده می‌کنند.

اندروید 12 گزینه‌های داخلی L2TP و PPTP را حذف کرد. TunnelForge برای سازمان‌ها، مدرسه‌ها، دانشگاه‌ها و شبکه‌های شخصی‌ای ساخته شده که هنوز نمی‌توانند سرورهای L2TP/IPsec موجود را جایگزین کنند.

قابلیت‌ها:

* L2TP با IPsec اختیاری و IKEv1
* حالت VPN برای کل دستگاه
* حالت فقط پروکسی با شنونده‌های محلی HTTP و SOCKS5
* مسیریابی برنامه‌ها با فهرست ورود یا خروج
* چند پروفایل با نگهداری محلی اطلاعات ورود
* DNS سفارشی شامل UDP، TCP، TLS و HTTPS
* MTU قابل تنظیم
* وضعیت اتصال و گزارش‌های محلی دقیق

TunnelForge سرویس یا حساب VPN ارائه نمی‌کند. برای استفاده به دسترسی به یک سرور VPN سازگار نیاز دارید.', description_fa_source = 'official' WHERE package_name = 'io.github.evokelektrique.tunnelforge' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Restoid به شما کنترل کاملی بر پشتیبان‌گیری از برنامه‌هایتان از طریق یک رابط کاربری تمیز، مدرن و ساده می‌دهد. این ابزار که توسط موتور متن‌باز «restic» قدرت گرفته، برای کاربرانی ساخته شده است که خواهان پشتیبان‌گیری‌های قدرتمند، رمزنگاری‌شده و با قابلیت حذف داده‌های تکراری (deduplication) هستند.

دسترسی روت برای خواندن و نوشتن در دایرکتوری‌های داده خصوصی برنامه‌ها کاملاً الزامی است.

ویژگی‌ها:
* قدرت‌گرفته از Restic: بهره‌گیری از سرعت، امنیت و کارایی restic برای پشتیبان‌گیری‌های محلی، فشرده‌سازی‌شده با حذف داده‌های تکراری و رمزنگاری‌شده.
* پشتیبان‌گیری انتخابی: دقیقاً انتخاب کنید که کدام برنامه‌های نصب‌شده توسط کاربر نیاز به ذخیره‌سازی دارند.
* کنترل دقیق: انتخاب جزئی موارد شامل برای هر برنامه: فایل‌های APK، داده‌های کاربر، داده‌های محافظت‌شده توسط دستگاه، فایل‌های خارجی/OBB یا فایل‌های رسانه‌ای.
* مدیریت منعطف مخازن: ایجاد و مدیریت مخازن در تمامی بک‌اندهای بومی restic: دایرکتوری محلی، SFTP، سرور REST و Amazon S3/MinIO.
* مدیریت Snapshotها: مرور آسان Snapshotهای تاریخی پشتیبان‌گیری، مشاهده جزئیات موارد پشتیبان‌گیری شده و حذف داده‌های قدیمی برای آزادسازی فضا.
* بازیابی جراحی (دقیق): بازیابی کامل برنامه‌ها یا فقط بخش‌های خاص (مثلاً بازیابی فقط داده‌های برنامه بدون بازنویسی فایل APK).
* زمان‌بندی خودکار: تنظیم پشتیبان‌گیری‌های دوره‌ای با فواصل زمانی و شرایط آغازین قابل شخصی‌سازی (باتری، در حال شارژ و وضعیت شبکه).
* محافظت در برابر دانگرید: جلوگیری از جایگزینی تصادفی نسخه جدید یک برنامه با نسخه قدیمی‌تر هنگام بازیابی.', description_fa_source = 'official' WHERE package_name = 'io.github.hddq.restoid' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'یک نرم افزار متن باز که به شما اجازه می دهد به راحتی و بصورت خودکار بتوانید رمز های یکبار مصرف یا پویا بانک های مختلف را به صورت خودکار از پیامک های بانک کپی کنید.

با این برنامه دیگر نیازی به حفظ کردن رمز های طولانی و پرش بین برنامه ها ندارید! به راحتی رمز خود را کپی کنید!

این نرم افزار به صورت کاملا آفلاین و بدون نیاز به دسترسی اینترنت کار می کند، با خیال راحت از این برنامه کاربردی و رایگان استفاده کنید.
