اگر هر گونه مشکل یا پیشنهادی دارید، می توانید از طریق سایت گیت هاب با ما در میان بگذارید:
https://github.com/jd1378/otphelper/issues', description_fa_source = 'official' WHERE package_name = 'io.github.jd1378.otphelper' AND description_fa IS NULL;
UPDATE apps SET description_fa = '‏Custom RR یک برنامه همراه رایگان و متن‌باز برای جامعه ماددینگ اندروید است. همه چیز را در یک جا گرد می‌آورد: کدام رام‌های سفارشی و ریکاوری‌ها به‌طور رسمی از دستگاه شما پشتیبانی می‌کنند، کدام Treble GSI را می‌توانید فلش کنید و از کجا آن‌ها را دانلود کنید. دیگر خبری از پریدن میان ویکی LineageOS، سه کانال تلگرام، یک پوشه SourceForge و چهارده زبانه مرورگر نیست.

ویژگی‌ها:

‏18 رام که فعالانه نگهداری می‌شوند (LineageOS، crDroid، PixelOS، Project Elixir، Evolution X، DerpFest، UN1CA، BlissROMs، /e/، GrapheneOS، CalyxOS، DivestOS، RisingOS Revived، VoltageOS و موارد دیگر)، هرکدام با توضیحات، ویژگی‌ها، اسکرین‌شات و پیوند یک‌ضربه‌ای به صفحه دانلود رسمی.

بیش از ۵۰۰ دستگاه که به‌صورت زنده از ویکی رسمی LineageOS و مخزن PixelOS official_devices گرفته می‌شوند و هر شب به‌روزرسانی می‌گردند.

ریکاوری‌های اصلی: TWRP، OrangeFox، PBRP، SHRP، با پشتیبانی برای هر دستگاه و دانلودهای مستقیم.

مرکز Treble و GSI: نشان‌های وضعیت برای هر پروژه، دانلودهای مستقیم GSI، فهرست متعارف ویکی TrebleDroid، یک برگه راهنمای A-only در برابر A/B و arm64 در برابر arm32_binder64، یک روند فلش ۶ مرحله‌ای و پرسش‌های متداول «GSI بالا می‌آید اما دوربین کار نمی‌کند».

تلفن خود را انتخاب کنید و کل برنامه به رام‌ها و ریکاوری‌هایی فیلتر می‌شود که به‌طور رسمی از آن پشتیبانی می‌کنند. صفحات برند هر دستگاه و هر رام/ریکاوری را که برای Xiaomi، OnePlus، Samsung، Pixel، Realme، POCO، Nothing و دیگران در نظر گرفته شده نشان می‌دهند.

پروژه‌های متوقف‌شده به‌وضوح علامت‌گذاری شده‌اند. رام‌های بایگانی‌شده (ArrowOS، DotOS، Havoc-OS، RisingOS اصلی و دیگران) تاریخ آخرین ساخت و پیشنهاد یک جانشین را نشان می‌دهند تا کدی را که سال‌هاست منتشر نشده فلش نکنید.

ساخت‌های غیررسمی و نگهداری‌شده توسط جامعه بخش جداگانه و به‌وضوح برچسب‌خورده خود را دارند، بنابراین همیشه می‌دانید چه چیزی رسمی است و چه چیزی پورت جامعه. از افزوده‌های اخیر می‌توان به پشتیبانی از Galaxy S24 Ultra اشاره کرد.

بنرهای هشدار پروژه پیش از فلش، نکات مهم مرتبط با جامعه را برجسته می‌کنند.

سیگنال‌های تازگی روی هر ورودی (فعال / ماهانه / متوقف‌شده، تاریخ آخرین ساخت) که با یک کار خودکار شبانه که پروژه‌های روبه‌خاموشی را علامت‌گذاری می‌کند، به‌روز نگه داشته می‌شوند.

راهنماهای گام‌به‌گام فلش برای رام‌ها و ریکاوری‌ها که برای هر دسته جاسازی شده‌اند.

با یک کاتالوگ داخلی کاملاً آفلاین کار می‌کند، سپس هنگام راه‌اندازی از GitHub به‌روزرسانی می‌شود تا رام‌ها و دستگاه‌های جدید بدون به‌روزرسانی برنامه ظاهر شوند.

‏Material 3 با رنگ پویا، تم‌های روشن / تیره / AMOLED و چیدمان‌های سازگار برای تلفن، تبلت و دسکتاپ.

پیوندهای عمیق برای هر رام، ریکاوری، دستگاه و برند که اشتراک‌گذاری آن‌ها در رشته‌ها آسان است.

بدون ردیابی، بدون تحلیل، بدون تبلیغات و بدون نیاز به سرویس‌های Google Play. تحت مجوز GPL-3.0؛ کد منبع در GitHub.', description_fa_source = 'official' WHERE package_name = 'io.github.monsiu.custom_rr' AND description_fa IS NULL;
UPDATE apps SET description_fa = '# OCR

یک برنامه اندروید OCR مبتنی بر Tesseract که می‌تواند متون روی تصاویر را تشخیص دهد.

حال این برنامه مبتنی بر <a href="https://github.com/tesseract-ocr/tesseract/blob/master/README.md">Tesseract 5 </a> است (از نسخه ۳) و اولین برنامه اندرویدی مبتنی بر Tesseract 5 است.

###پس از بارگیری داده‌های آموزشی، برنامه همه کارها را به‌صورت آفلاین در دستگاه شما انجام می‌دهد.

ترجمه این برنامه در [Hosted Weblate](https://hosted.weblate.org/projects/android-ocr).

🚀 <font color="#2467d6"><b>امکانات</b></font>
* بالاترین دقت و سریع‌ترین نتیجه.
* استخراج متن از تصاویر.
* روگرفت داده‌ها به حافظه موقت.
* انتخاب هر بخشی از داده‌ها.
* پردازش چندین زبان در یک تصویر (نیازمند تغییرات در تنظیمات).
* مبتنی بر آخرین <a href="https://github.com/tesseract-ocr/tessdoc/blob/master/Data-Files.md">داده‌های آموزشی</a>
* بیش از ۱۲۰ <a href="https://tesseract-ocr.github.io/tessdoc/Data-Files">زبان</a> شناسایی شده.
* ۳ نوع داده برای مثال <a href="https://github.com/tesseract-ocr/tessdata">استاندارد</a>، <a href="https://github.com/tesseract-ocr/tessdata_best">بهترین</a>، <a href="https://github.com/tesseract-ocr/tessdata_fast">سریع</a>و برای اطلاعات بیشتر <a href="https://github.com/tesseract-ocr/tessdoc/blob/master/Data-Files.md">اینجا را کلیک نمایید</a>.
* تشخیص ریاضی/شناسایی معادله (هنوز آزمایش نشده)
* پردازش مستقیم تصاویر گالری وسیله شما از طریق منوی هم‌رسانی.

<font color="#2467d6"><b>مجوزهای مورد نیاز</b></font>

* اینترنت: بارگیری داده‌های آموزشی
* وضعیت دسترسی به اینترنت: برای بارگیری داده‌های آموزشی.
* توجه: هیچ یک از داده‌های شما به جایی ارسال نمی‌شود.

📓 <font color="#2467d6"><b>مجوز</b></font>

* Tesseract and Tesseract Data: <a href="https://github.com/tesseract-ocr/tesseract/blob/master/LICENSE">Apache 2.0</a>.
* Tesseract4Android: <a href="https://github.com/adaptech-cz/Tesseract4Android/blob/master/LICENSE">Apache 2.0</a>.
* ImageCropper: <a href="https://github.com/ArthurHub/Android-Image-Cropper/blob/master/LICENSE.txt">Apache 2.0</a>.
* SpinnerDialog: <a href="https://github.com/MdFarhanRaja/SearchableSpinner/blob/master/LICENSE">[Apache 2.0</a>

ممکن شده توسط کتابخانه <a href="https://github.com/adaptech-cz/Tesseract4Android">Tesseract4Android</a>.

اگر می‌خواهید از نسخه مبتنی بر Tesseract 4 استفاده کنید، می‌توانید از نسخه قدیمی این برنامه (قبل از نسخه ۳) استفاده کنید.', description_fa_source = 'official' WHERE package_name = 'io.github.subhamtyagi.ocr' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'TrovePass گذرواژهٔ هر سایت و برنامهٔ شما را از یک گذرواژهٔ اصلی می‌سازد — آفلاین، بدون حساب، فقط روی همین دستگاه.

چه کاری می‌کند

* گذرواژهٔ یک سایت را از گذرواژهٔ اصلی شما می‌سازد: همان سایت، همان نام کاربری و همان گزینه‌ها همیشه همان گذرواژه را می‌دهند — روی هر دستگاهی، بدون آنکه چیزی ذخیره شود.
* سایت، نام کاربری و گزینه‌هایی را که به کار برده‌اید به یاد می‌سپارد، پس هرگز لازم نیست شمارنده یا دسته‌های نویسه را پشت یک گذرواژه از یاد ببرید.
* تنها زمانی گذرواژه‌ای ذخیره می‌کند که ذخیره را بزنید، و آنچه ذخیره می‌شود را با کلیدی که همین دستگاه نگه می‌دارد مهر می‌کند.
* اثری از گذرواژهٔ اصلی شما را نشان می‌دهد — کاشی چهارگوشی در دو رنگ — تا اشتباه تایپی پیش از ساخته‌شدن گذرواژهٔ نادرست دیده شود.
* به 85 زبان سخن می‌گوید و هیچ اجازه‌ای نمی‌خواهد.

چه کاری نمی‌کند

* نه حساب، نه ورود، نه همگام‌سازی، نه تله‌متری، نه تحلیل.
* نه کد شبکه‌ای و نه اجازه‌ای اعلام‌شده: اینجا چیزی نیست که بتواند چیزی را جایی بفرستد.
* گذرواژهٔ اصلی هرگز و به هیچ شکلی ذخیره نمی‌شود. چیزی هم از شما نمی‌خواهد که قفلی را باز کنید — گذرواژه‌های ذخیره‌شده با کلیدی مهر شده‌اند که هرگز از دستگاه بیرون نمی‌رود.

همان گذرواژه‌های LESSPASS

هر دو برنامه گذرواژه را از همان ورودی‌ها دقیقاً به یک شیوه می‌سازند، با همان ریزه‌کاری‌ها؛ پس گذرواژه‌ای که در LessPass ساخته‌اید همان گذرواژه‌ای است که TrovePass به شما می‌دهد. این پیاده‌سازی مستقل آن قالب منتشرشده است، نه انشعابی از آن.

برای چه کسانی

برای هر کس که به‌جای پنجاه گذرواژه ترجیح می‌دهد یک گذرواژهٔ اصلی را به یاد بسپارد: نام سایت و گذرواژهٔ اصلی کافی است — روی هر دستگاهی، بدون ساختن حساب و بدون چیزی که با گم‌شدن گوشی از دست برود.

مجوز

GPL-3.0-or-later. کد منبع کامل این برنامه تحت همین مجوز منتشر شده است.', description_fa_source = 'official' WHERE package_name = 'io.github.u_20240816.trovepass' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Unstoppable wallet is purposely built as a decentralized management tool for cryptocurrencies.

It is engineered to serve privacy-conscious individuals looking to manage and invest in Bitcoin, Ethereum and other cryptocurrencies in a sovereign and professional manner.

Unstoppable is built with the following in mind:

- Capital Should Be Free >> It’s built to provide users with genuinely independent control over their capital.

- Capital Should Be Borderless >> It works outside the traditional finance layer and acts as a Swiss knife to the world of decentralized finances (DeFi).

- Capital Should Be Private >> It doesn’t leak private data, it has no means to track users, and takes extra measures to ensure privacy on multiple layers.

If the above rhymes well with you then Unstoppable is for you! And we are here to focus on your unique needs and serve you in the best possible manner.

WALLET FEATURES:

- Non-Custodial Multi-wallet >> Manage any number of cryptocurrencies across multiple portfolio-style wallets in a non-custodial manner. This wallet is like your own bank where you are the only client and the only one in charge. It’s designed to keep assets secure and easy to restore even if the phone is stolen and tampered with.

- Investment Oriented Wallet >> Unstoppable brings unmatched cryptocurrency market analytics to your device: advanced sorting, curated categorization, extensive search filtering, and event-based alerting features.

- Universal Wallet >> It supports all mainstream blockchains and is built in a standard compliant manner enabling users to use just one wallet app for everything crypto.

- A Bitcoin Wallet >> The wallet packs some of the most advanced Bitcoin features available: SPV enabled, BIP 44/49/84/86/69 compliant, Bitcoin timelocks, custom transaction fees, and more.

- A DeFi Wallet >> Full support for decentralized token swaps on Ethereum, Binance Smart Chain, Polygon, Avalanche, Solana, and more. Also, the ability to interact with any smart contract-powered service on the blockchain via the WalletConnect protocol.

- Ethereum Wallet >> Full support for Ethereum blockchain, its growing ecosystem of tokens (ERC20, NFT tokens, etc.), and other decentralized services such as ENS (Ethereum Name Service).

- Ethereum L2 Wallet >> Arbitrum, Optimism, Polygon support.

- Avalanche Wallet >> Full support for Avalanche C-Chain blockchain.

- Binance Wallet >> Full support for original Binance Chain (incl. BEP2) and Binance Smart Chain.

- Crypto Academy >> The app includes two courses meant to onboard newcomers into the world of cryptocurrencies and the DeFi ecosystem in an easy-to-digest manner covering essential aspects of cryptocurrency security, storage, privacy, transacting, and exchanging.

- Wallet for Privacy Coins >> Fully supports major privacy coins (ZCash, DASH) in an SPV manner. One of the very few wallets capable of supporting fully shielded Zcash transactions as well as the ability to privatize Bitcoin transactions.

- Decentralized Wallet >> Designed to work with most major blockchains in a decentralized manner where an app doesn''t depend on some server of a wallet provider to send/receive transactions but interacts with blockchain networks directly.

- Privacy Focused >> Designed to allow for privacy even in the most privacy-breaching scenarios. There are no user accounts keeping your records, no identity checks that risk exposing your financials to the world, and no interaction with traditional finance layers. The app is partially TOR enabled and VPN support coming soon.

- Fully Open Source >> The most transparent wallet application built to date. The entire 4-year production process of the app is openly accessible online along with 100% of its code for anyone to evaluate or reuse in other projects. Verified and audited by third parties.

Be Unstoppable!', description_fa_source = 'official' WHERE package_name = 'io.horizontalsystems.bankwallet' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Olvid، اولین برنامه پیام‌رسانی فوری خصوصی برای همه است. پیام، عکس و فایل ارسال کنید و تماس‌های تلفنی و تصویری امن برقرار کنید.

یک پیام‌رسان «خصوصی» چیست؟

این یک پیام‌رسان است که:
- مخاطبین جدید را به شما تحمیل نمی‌کند. شما کنترل را در دست دارید: خودتان انتخاب می‌کنید که با چه کسی می‌خواهید گفتگو کنید. Olvid روش‌های مختلفی را برای برقراری ارتباط با سایر کاربران Olvid، چه به صورت حضوری و چه از راه دور، ارائه می‌دهد.
- به هیچ داده شخصی نیاز ندارد. Olvid شماره تلفن یا ایمیل شما را درخواست نمی‌کند. بر خلاف پیام‌رسان قبلی شما، Olvid هرگز دسترسی به دفترچه آدرس شما را درخواست نخواهد کرد.
- در آن هرگز پیام‌های ناخواسته یا پیام‌هایی از منبع ناشناس دریافت نخواهید کرد.
- در آن، همه تبادلات از همان امنیت و حریم خصوصی یک گفتگوی واقعی در یک فضای بسته برخوردار هستند. Olvid به طور پیش‌فرض، همیشه و برای همه چیزهایی که ارسال یا دریافت می‌کنید، رمزگذاری سرتاسری و احراز هویت سرتاسری را ارائه می‌دهد.

Olvid فضاهای امنی را برای شما تضمین می‌کند که در برابر تهاجمات خارجی مصون هستند و شما را از سر و صدای دیجیتال و خشونت سایر شبکه‌های اجتماعی جدا می‌کنند. گروه‌هایی با خانواده، دوستان و همکاران کلیدی خود ایجاد کنید. خبری از هرزنامه یا تبلیغات نخواهد بود. شما در نهایت کنترل کامل ارتباطات خود را به دست می‌گیرید.

Olvid طوری طراحی شده است که بهترین مکان برای تبادل نظر در مورد موضوعات مهم با افرادی باشد که برای شما مهم هستند.

Olvid - فناوری

در قلب Olvid، یک «موتور رمزنگاری» وجود دارد که حاصل سال‌ها تحقیق است و به طور ریاضی، یکپارچگی، محرمانگی و ناشناس بودن ارتباطات شما را اثبات می‌کند.', description_fa_source = 'official' WHERE package_name = 'io.olvid.messenger.nogoogle' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'گره‌نما یک بررسی‌کننده عمومی وب‌سایت برای کاربرانی است که با محدودیت‌های اینترنت مواجه‌اند. این برنامه به کاربران کمک می‌کند تا مشخص کنند آیا یک سرویس از طریق اتصال فعلی قابل دسترسی است یا فیلتر شده و در دسترس نیست.', description_fa_source = 'official' WHERE package_name = 'ir.ammari.nodelook' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'با این برنامه می‌تونید یک فایل صوتی از نوع wave رو در داخل یک عکس پنهان کنید بدون اینکه حجم عکس تغیر خاصی بکنه یا ظاهر عکس عوض بشه. 

عکس‌هایی رو که به این صورت تغییر داده‌شدن می‌تونید توی همین برنامه باز کنید تا فایل صوتی از داخلش استخراج بشه.

در حال حاضر بهترین روش استفاده، ضبط صدا از طریق برنامه است و البته فایل‌های با فرمت wav هم پشتیبانی می‌شوند. فرمت‌های دیگر مثل mp3 پشتیبانی نمی‌شوند.', description_fa_source = 'official' WHERE package_name = 'ir.mrahimy.conceal' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'ام‌پی‌وی اندروید یک پخش‌کنندهٔ ویدیویی برای سیستم‌عامل اندروید مبتنی بر <a href="https://github.com/mpv-player/mpv">libmpv</a> است.

امکانات:
* کدگشایی ویدیو سخت‌افزاری و نرم‌افزاری
* جابه‌جایی، تغییر حجم صدا و روشنایی و ... مبتنی بر حرکات
