* پشتیبانی از پخش در پس‌زمینه، تصویر-در-تصویر، صفحه کلید و …', description_fa_source = 'official' WHERE package_name = 'is.xyz.mpv' AND description_fa IS NULL;
UPDATE apps SET description_fa = '<b>Warning:</b> Creating new accounts in the FOSS version not possible anymore, you have to create an account in the official build and then login to the FOSS.
<b>هشدار:</b> این ساخت بر پایه ی یک انشعاب کاملاً آزاد است. پروژهٔ اصلی همیشه در انتشار کد مبدأ برای نگارش‌های اخیر سریع نیست.

یک کلاینت برای پلت فرم پیام‌رسان تلگرام. با دوستان خود گفتگو کنید و یا گروه بسازید و هر چیزی را در آن به اشتراک بگذارید. تمام پیام و گفتگوهای شما در فضای ابری تلگرام نگهداری ‌می‌شود.

هدف این پلتفرم پیام رسان دستگاه‌های موبایل است اما نسخه‌ای برای کامپیوتر و وب نیز برای کاربران وجود دارد.

چند بخش اختصاصی از کلاینت اصلی تلگرام حذف شد٬‌ از جمله سرویس گوگل پلی برای خدمات مکانیابی٬‌ HockeySDK برای به روز رسانی‌های خود و همچنین اعلام اعلامیه‌ها از طریق پیام رسان ابری گوگل. قابلیت اشتراک گذاری مکان بازسازی شده است از طربق OpenStreetMap.

پادویژگی: شبکهٔ غیرآزاد، چرا که سرور ها نرم‌افزاری انحصاری را اجرا می‌کنند.

کد منبع رسمی برنامه حاوی حبابهای باینری است پس کسانی را دنبال کن که با استفاده از این منابع چیزی می‌سازند. از این رو  ممکن است نسخه‌ها با کمی تاخیر در دسترس قرار بگیرند.', description_fa_source = 'official' WHERE package_name = 'it.belloworld.mercurygram' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'شطرنج برای Android یک برنامهٔ رایگان، متن‌باز و بدون تبلیغ است—فقط شطرنج. آفلاین بازی کنید، آنلاین رقابت کنید، معما حل کنید، وضعیت‌ها را بررسی کنید و همهٔ بازی‌هایتان را در یک مکان مرتب نگه دارید.

به روش خودتان بازی کنید

• آفلاین با موتور شطرنج داخلی بازی کنید.
• برای بازی آنلاین به Lichess یا FICS متصل شوید.
• چالش‌های Lichess را ایجاد یا قبول کنید و بازی‌های در حال انجام را ادامه دهید.
• از میان شطرنج استاندارد، Chess960 یا شطرنج اردکی آزمایشی انتخاب کنید.
• وضعیت‌های دلخواه را مستقیماً روی صفحه بچینید.

تمرین کنید و پیشرفت کنید

• معماهای Lichess را حل کنید.
• با مجموعه‌ای از مسائل مات در دو حرکت و وضعیت‌های تمرینی کار کنید.
• گشایش‌ها را با مرورگر داخلی ECO بررسی کنید.
• میان حرکت‌ها جابه‌جا شوید و بازی‌های کامل را مرور کنید.

بازی‌هایتان را مدیریت کنید

بازی‌ها را در پایگاه دادهٔ محلی ذخیره کنید و بر اساس جزئیاتی مانند بازیکن، رویداد، تاریخ یا نتیجه جست‌وجو کنید. بازی‌های ذخیره‌شده را ویرایش کنید، فایل‌های بازی را وارد یا صادر کنید و وضعیت‌ها یا بازی‌ها را از طریق برنامه‌های دیگر به اشتراک بگذارید.

شطرنج دسترس‌پذیر

شطرنج برای Android از صفحه‌خوان‌هایی مانند TalkBack پشتیبانی می‌کند. خانه‌های صفحه، مهره‌ها، حرکت‌ها و کنترل‌ها اطلاعات گفتاری ارائه می‌دهند تا کاربران صفحه‌خوان بتوانند پیمایش و بازی کنند.

حالت اختیاری «کشیدن دسترس‌پذیر» راه دیگری برای حرکت دادن مهره‌ها در اختیار بازیکنانی می‌گذارد که کشیدن معمولی برایشان دشوار است. زمان‌بندی آن برای نیازهای تعاملی گوناگون قابل تنظیم است. این حالت مستقل برای استفاده بدون TalkBack طراحی شده است.

روی صفحه‌ای بزرگ‌تر بازی کنید

صفحهٔ شطرنج را به تلویزیون یا نمایشگر دارای Chromecast منتقل کنید تا دیگران بازی را روی صفحه‌ای بزرگ‌تر دنبال کنند.

از موتور دلخواهتان استفاده کنید

شطرنج برای Android افزون بر موتور داخلی، از Open Exchange Protocol ‏(OEX) پشتیبانی می‌کند و امکان استفاده از موتورهای شطرنج سازگار شخص ثالث را پس از نصب فراهم می‌سازد.

چه به‌دنبال یک بازی سریع آفلاین، رقابت آنلاین در Lichess، تمرین تاکتیکی، کنترل‌های دسترس‌پذیر یا پایگاه دادهٔ قابل جست‌وجوی بازی‌ها باشید، شطرنج برای Android همه‌جا یک صفحهٔ شطرنج انعطاف‌پذیر در اختیارتان می‌گذارد.', description_fa_source = 'official' WHERE package_name = 'jwtc.android.chess' AND description_fa IS NULL;
