UPDATE apps SET description_fa = 'Use JamesDSP as a system-wide audio processing engine without any root access.

This app has several limitations that may be deal-breaking to some people; please read this whole document before using the app. Shizuku (Android 11+) or ADB access via a computer is required for the initial setup.

JamesDSP supports the following audio effects:
* Limiter control
* Output gain control
* Auto dynamic range compressor
* Dynamic bass boost
* Interpolating FIR equalizer
* Arbitrary response equalizer (Graphic EQ)
* ViPER-DDC
* Convolver
* Live-programmable DSP (scripting engine for audio effects)
* Analog modelling
* Soundstage wideness
* Crossfeed
* Virtual room effect (reverb)

Additionally, this app integrates directly with AutoEQ. Using AutoEQ integration, you can search and import frequency responses that aim to correct your headphone to a neutral sound. Go to ''Arbitrary response equalizer > Magnitude response > AutoEQ profiles'' to get started.

--- Limitations
* Apps blocking internal audio capture remain unprocessed (e.g., Spotify, Google Chrome)
* Apps using some types of HW-accelerated playback may cause issues and need to be manually excluded (e.g., some Unity games)
* Cannot coexist with (some) other audio effect apps (e.g., Wavelet and other apps that make use of the `DynamicsProcessing` Android API)

- Apps confirmed working:
* YouTube
* YouTube Music
* Amazon Music
* Deezer
* Poweramp
* Substreamer
* Twitch
* ...

- Unsupported apps include:
* Spotify (Note: Spotify ReVanced patch is required to support Spotify)
* Google Chrome
* SoundCloud
* ...

--- Translation
Please help us translate this app here: https://crowdin.com/project/rootlessjamesdsp
To request a new language that isn''t enabled on Crowdin yet, please open an issue here on GitHub and I will turn it on.', description_fa_source = 'official' WHERE package_name = 'me.timschneeberger.rootlessjamesdsp' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'PhoneTrack هو تطبيق يستخدم معلومات محلية للولوج الى داخل النظام.
Application works in background. Points are saved at chosen frequency and
uploaded to a server in real time. This logger works with
[https://gitlab.com/eneiluj/phonetrack-oc PhoneTrack Nextcloud app] or any
custom server (GET or POST HTTP requests). PhoneTrack app can also be remotely
controlled by SMS commands.

# Features

- Log to multiple destinations with multiple settings (frequency, min distance, min accuracy, significant move)
- Log to PhoneTrack Nextcloud app (PhoneTrack log job)
- Log to any server which can receive HTTP GET or POST requests (custom log job)
- Store positions when network is not available
- Remote control by SMS:
    - get position
    - activate alarm
    - start all logjobs
    - stop all logjobs
    - create a logjob
- Start on system boot
- Display devices of a Nextcloud PhoneTrack session on a map
- Dark theme
- Multi-Lingual User-Interface (translated on https://crowdin.com/project/phonetrack )

# Requirements

If you want to log to Nextcloud PhoneTrack app :

- Nextcloud instance running
- Nextcloud PhoneTrack app enabled

Otherwise, no requirements ! (Except Android>=4.1)

# Alternatives

If you don''t like this app and you are looking for alternatives: Have a look at the logging methods/apps
in PhoneTrack wiki : https://gitlab.com/eneiluj/phonetrack-oc/wikis/userdoc#logging-methods .', description_fa_source = 'official' WHERE package_name = 'net.eneiluj.nextcloud.phonetrack' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'TrackerControl allows users to monitor and control the widespread, ongoing, hidden data collection in mobile apps about user behaviour (''tracking'').

To detect tracking, TrackerControl combines the power of the Disconnect blocklist, used by Firefox, and our in-house blocklist is used, created from analysing <i>~2 000 000</i> apps! Additionally, TrackerControl supports custom blocklists.

This approach

- reveals the companies behind tracking,
- allows to block tracking selectively, and
- exposes the purposes of tracking, such as analytics or advertising.

The app also aims to educate about your rights under Data Protection Law, such the EU General Data Protection Regulation (GDPR).

Under the hood, TrackerControl uses Android''s VPN functionality, to analyse apps'' network communications <i>locally on the Android device</i>. This is accomplished through a local VPN server, to enable network traffic analysis by TrackerControl.

No root is required, other VPNs or Private DNS are not supported. No external VPN server is used, to keep your data safe! TrackerControl even protects you against <i>DNS cloaking</i>, a popular technique to hide trackers in websites and apps.

TrackerControl will always be free and open source, being a research project.', description_fa_source = 'official' WHERE package_name = 'net.kollnig.missioncontrol.fdroid' AND description_fa IS NULL;
UPDATE apps SET description_fa = '7 day free trial: All features, no ads, cancel anytime. Plans starting at $2.39 / month.

تنها VPNی که نمی‌تواند از شما جاسوسی کند. ساخته‌شده در سوئیس. ساخته‌شده توسط مدافعان حریم خصوصی. The world''s first mixnet for online anonymity.

- NO-NAME SIGNUP: No email required. حساب‌ کاربری‌های دانش صفر. بیشترین تعداد ارزهای دیجیتالِ پذیرفته‌شده برای پرداخت در میان تمام VPNها. برای ناشناسی کامل پرداخت نقدی پذیرفته می‌شود.
- DECENTRALIZED VPN technology
- MOST CRYPTOCURRENCIES ACCEPTED of any VPN
- 70+ COUNTRIES with hundreds of independent servers
- UP TO 10 DEVICES with one anonymous code

### BROWSE WITHOUT A TRACE

Tired of wondering who''s watching you? شرکت‌ها در حال جمع‌آوری داده‌های شخصی شما هستند؟ به‌خاطر جایی که هستید به اطلاعات دسترسی ندارید؟

While other VPNs promise not to keep logs, with NymVPN there is no point on the decentralized network that can connect your IP address with what you do online. حریم خصوصی شما به‌صورت پیش‌فرض تضمین شده است. Your online activity cannot be tied back to you by advertisers, network operators, or centralized infrastructure. You can browse and communicate without leaving a data trail  across the internet.

### CHOOSE YOUR PRIVACY LEVEL

Fast Mode

- High-speed browsing and streaming
- 2-hop decentralized VPN
- AmneziaWG (WireGuard) protection

حالت ناشناس

- Maximum anonymity for messaging, email, and financial transactions
- 5-hop Noise Generating Mixnet
- Resists advanced traffic analysis

### ESSENTIAL FEATURES

- Entry & exit server selection
- Multi-layer encryption
- dVPN AmneziaWG (WireGuard) support
- Kill switch prevents data leaks
- Advanced anti-censorship technology
- تونلینگ تفکیکی
- Custom DNS
- Key rotation for cryptographic security
- تجربه‌ای عاری از هرگونه تبلیغ
- 100% open source software

### WHY NYMVPN IS DIFFERENT

Most VPNs rely on centralized servers and ask you to trust their "no-logs" promises. NymVPN به‌گونه‌ای متفاوت ساخته شده است.

- Decentralized VPN (dVPN) architecture: Traffic is routed through independently operated servers. No one can see both who you are and what you do online.

- Metadata protection: NymVPN protects traffic patterns, timing, and routing information. حتی داده‌های رمزگذاری‌شده هم می‌توانند متادیتا را افشا کنند. Nym prevents that.

- Two privacy modes, one app: The dVPN mode uses a high-performance 2-hop decentralized VPN. The ANONYMOUS  mode uses a 5-hop mixnet for maximum anonymity.

- Noise Generating Mixnet technology: Your traffic is mixed with cover traffic, making correlation and AI-driven traffic analysis extremely difficult.

- حساب‌های دانش صفر از اساس: ثبت‌نام بدون ایمیل. بدون داده‌های شخصی. حساب‌ها به نحوه استفاده، قابل پیوند نیستند. برای ناشناسی کامل از پرداخت‌های ارز دیجیتال و نقدی پشتیبانی می‌کند.

- شبکه‌سازی مقاوم در برابر سانسور: با AmneziaWG، QUIC، و گزینه‌های انتقال stealth ساخته شده است تا در محیط‌هایی با محدودیت شدید اینترنتی کار کند.

- Open-source and independently audited.
- Built by academic cryptographers

### NYMVPN IS PERFECT FOR:

- Streaming and browsing without being tracked
- Secure public WiFi connections
- Anyone in restrictive countries needing reliable access
- People who want true anonymity, not just hidden IP addresses
- Journalists and activists needing untraceable communication
- Featured in PCMag, TechRadar, Forbes, Bloomberg, Tom''s Guide

