UPDATE apps SET description_fa = 'تاندربرد یک برنامه رایانامه قدرتمند و متمرکز بر حریم خصوصی است. با استفاده از گزینه صندوق ورودی یکپارچه برای حداکثر بهره‌وری، به راحتی چندین حساب رایانامه را از یک برنامه مدیریت کنید. تاندربرد که بر اساس فناوری متن‌باز ساخته شده و توسط یک تیم اختصاصی از توسعه دهندگان در کنار یک جامعه سراسری از داوطلبان پشتیبانی می شود، هرگز با داده های خصوصی شما به عنوان یک محصول رفتار نمی کند. صرفاً توسط کمک‌های مالی کاربران ما پشتیبانی می‌شود، بنابراین دیگر هیچ‌وقت مجبور نخواهید شد که دوباره تبلیغات را در ترکیب با رایانامه‌هایتان مشاهده کنید.

<b>کارهایی که می‌توانید انجام دهید</b>
<ul>
  <li>برنامه‌ها و وب‌های متعدد مرتبط با رایانامه را کنار بگذارید. از یک برنامه، با صندوق ورودی یکپارچه اختیاری، استفاده کنید تا یک روز با تمام قدرت داشته باشید.</li>
  <li>از یک کارخواه رایانامه دوستدار حریم خصوصی که هرگز داده های شخصی شما را جمع آوری نمی‌کند یا نمی‌فروشد، لذت ببرید. ما مستقیماً شما را به ارائه‌دهنده‌های خدمت رایانامه متصل می کنیم. فقط همین!</li>
  <li>با استفاده از رمزگذاری رایانامه OpenPGP (PGP/MIME) با برنامه OpenKeychain، برای رمزگذاری و رمزگشایی پیام‌های خود، حریم خصوصی خود را به سطح بالاتر ببرید.</li>
  <li>انتخاب کنید تا رایانامه خود را فوراً، در فواصل زمانی تعیین شده یا بر اساس درخواست همگام کنید. هر طور که بخواهید رایانامه خود را چک کنید، این به شما بستگی دارد!</li>
  <li>پیام‌های مهم خود را با استفاده از جستجوی محلی و برخط پیدا کنید.</li>
</ul>

<b>سازگاری</b>
<ul>
  <li>تاندربرد با پروتکل های IMAP و POP3 کار می کند و از طیف گسترده ای از ارائه دهندگان رایانامه از جمله Gmail، Outlook، Yahoo Mail، iCloud و غیره پشتیبانی می کند.</li>
</ul>

<b>چرا از تاندربرد استفاده کنیم</b>
<ul>
  <li>نام قابل اعتماد برای رایانامه در طول بیش از ۲۰ سال - اکنون در اندروید.</li>
  <li>تاندربرد به طور کامل از طریق مشارکت های داوطلبانه کاربران ما حمایت و تأمین می شود. ما اطلاعات شخصی شما را استخراج نمی کنیم. شما هرگز به عنوان محصول مورد بهره‌برداری قرار نمی‌گیرید.</li>
  <li>ساخته شده توسط تیمی که به اندازه شما کارآمد فکر می کند. ما می خواهیم که شما کمترین زمان خود را برای استفاده از برنامه صرف کنید و در ازای آن بیشترین آورده را داشته باشید.</li>
  <li>با مشارکت کنندگان از سراسر جهان، تاندربرد برای اندروید به بیش از ۲۰ زبان ترجمه شده است.</li>
  <li>توسط MZLA Technologies Corporation، یک شرکت تابعه کاملا متعلق به بنیاد موزیلا پشتیبانی می شود.</li>
</ul>

<b>متن‌باز بودن و جامعه</b>
<ul>
  <li>تاندربرد رایگان و منبع باز است، به این معنی که کد آن برای دیدن، تغییر، استفاده و اشتراک‌گذاری آزادانه در دسترس است. مجوز آن همچنین تضمین می کند که برای همیشه آزاد خواهد بود. شما می‌توانید تاندربرد را به عنوان هدیه‌ای از جانب هزاران مشارکت‌کننده در نظر بگیرید.</li>
  <li>توسعه‌ ما در فضای باز با به‌روزرسانی‌های منظم و شفاف در وبلاگ و لیست‌های پستی خود می‌باشد.</li>
  <li>پشتیبانی کاربر به وسیله جامعه سراسری ما قدرت می‌گیرد. پاسخ‌های مورد نیاز خود را بیابید، یا به عنوان یک مشارکت‌کننده فعالیت کنید که پاسخ دادن به سؤالات، ترجمه برنامه، یا گفتگو با دوستان و خانواده‌تان درباره تاندربرد، می‌تواند باشد.</li>
</ul>', description_fa_source = 'official' WHERE package_name = 'net.thunderbird.android' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'با دانلود بتای تاندربرد و دسترسی زودهنگام به آخرین ویژگی‌ها و رفع اشکال‌ها قبل از انتشار رسمی، کمک کنید تا نسخه بعدی تاندربرد عالی‌ترین باشد. آزمایش و بازخورد شما مهم است، بنابراین لطفاً اشکالات، ناهنجاری‌های احتمالی را گزارش کنید و نظرات خود را با ما در میان بگذارید!

