UPDATE apps SET description_fa = 'یکی از بهترین برنامه های رایگان و منبع باز مسدود کننده تبلیغات برای گوشی های اندروید

این برنامه برای دستگاه های روت شده و بدون روت در دسترس است
در حالت استفاده از روت برنامه فایل hosts سیستم شما را به روز رسانی می کند که شامل لیستی از نگاشت ها بین نام host و آدرس های IP است
در حالت استفاده بدون روت برنامه از ویژگی VPN برای مسدود کردن اتصالات خروجی به تبلیغات و ردیاب ها استفاده می کند
بنابراین هنگامی که یک برنامه از یک host در آن فایل درخواست تبلیغ یا ردیاب می کند این درخواست به IP محلی 127.0.0.1 منتقل می شود که هیچ کاری انجام نمی دهد

شما می‌توانید تبلیغات از پیش تعریف‌ شده و فهرست‌ های مسدود کننده را به‌ عنوان فایل‌ های hosts از داخل برنامه دانلود کنید تا در آن گنجانده شود همچنین می توانید از فایل های خود استفاده کنید و host های خاصی را به لیست های مجاز و مسدود شده اضافه کنید
گزینه‌ هایی برای اجرای یک وب سرور محلی در پاسخ به نام‌ های host مسدود شده و انتقال درخواست‌ها به آدرس IP مورد نظر شما وجود دارد', description_fa_source = 'official' WHERE package_name = 'org.adaway' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'با CalyxVPN,شما می‌توانید تمام ترافیک شبکه خود را به‌طور ایمن رمزگذاری کرده و آن را به موسسه Calyx هدایت کنید.

• وی پی ان ناشناس: بدون حساب کاربری و بدون ورود به سیستم.
•آدرس آیپی ناشناس:هنگامی که اتصال VPN فعال است، تمام سرورهای اینترنت شما را به عنوان منبعی از یک IP ناشناس میزبانی شده توسط Calyx می بینند.
• رایگان:این یک سرویس رایگان توسط موسسه calyx می باشد.
•منبع باز بودن:کلاینت و سرور هر دو نرم افزار 100% رایگان و متن باز هستند.
•بدون نشت IPv6: CalyxVPN ترافیک IPv6 را افشا نمی کند (نیاز به روت است).
• بدون نشت DNS: CalyxVPN هم روی کلاینت و هم روی سرور پیکربندی شده است تا از هرگونه نشت DNS جلوگیری کند. تمام درخواست های DNS به صورت ناشناس توسط Calyx زمانی که VPN روشن است بررسی می شود.
• دور زدن: هنگامی که گزینه "استفاده از پل ها" فعال است، تمام ترافیک شما به عنوان ترافیک وب عادی پنهان می شود تا برخی از سیستم های سانسوری که ترافیک VPN را مسدود می کنند، دور بزنند.

مانند تمام VPN ها، CalyxVPN تنها هنگام عبور از شبکه، امنیت را به داده های شما اضافه می کند. نمی تواند از محتوای داده های شما که ذخیره شده یا به یک وب سایت می دهید محافظت کند.همچنین از تبلیغات و ردیابی در برنامه ها یا مرورگر وب شما جلوگیری نمی کند (به جز زمانی که این ردیابی بر اساس آدرس IP شما باشد).', description_fa_source = 'official' WHERE package_name = 'org.calyxinstitute.vpn' AND description_fa IS NULL;
UPDATE apps SET description_fa = '<p>
