اختیار آن فهرست سرورها با شماست. در تنظیمات اشتراک می‌توانید هر سروری را
خاموش کنید، همه را خاموش کنید — آن‌وقت Tane دوباره دفتری می‌شود که هرگز وصل
نمی‌شود — یا نشانی سرور دیگری را بیفزایید. هرکسی می‌تواند سرور خودش را
بگرداند و Tane با آن هم به‌خوبی کار می‌کند.

