UPDATE apps SET description_fa = 'ایا وبسایت‌ها و اپ شبکه‌های اجتماعی مسدود شده‌اند؟ آیا شبکه شما به صورت غیرمعمولی آهسته است؟ کاوشگر OONI را اجرا کنید تا متوجه شوید!

با این برنامه، شما مسدود بودن وبسایت‌ها و پیام‌‌رسان‌ها را مورد آزمون، سرعت و کارایی شبکه خود را اندازه‌گیری و سیستم‌های مسئول سانسور و نظارت شبکه خود را بررسی خواهید کرد.

کاوشگر OONI توسط رصد خانه آزاد دخالت در شبکه (OONI) که یک پروژه‌ی نرم افزار آزاد (تحت پروژه‌ی Tor) است، توسعه یافته و هدف آن برملا ساختن سانسور اینترنت در سراسر دنیاست.

از سال 2012، جامعه‌ی جهانی OONI میلیون‌ها سنجش شبکه از بیش از 200 کشور را جمع‌آوری و موارد متعددی از دخالت در شبکه را برملا کرده.

▶ Collect evidence of internet censorship
شما می‌توانید وضعیت و چگونگی مسدود بودن وبسایت‌ها و پیام‌رسان‌ها را بررسی کنید. داده‌های سنجش شبکه‌ای که شما جمع‌آوری می‌کنید می‌تواند سندی بر سانسور اینترنت باشد.

▶ Detect systems responsible for censorship and surveillance
تست‌های کاوشگر OONI همچنین برای آشکار ساختن حضور سیستم‌هایی که ممکن است مسئول سانسور و نظارت باشند (middleboxes) طراحی شده‌اند.

▶ Measure the speed and performance of your network
شما می‌توانید سرعت و کارایی شبکه خود را با استفاده از تست تشخیص شبکه (NDT) در OONI اندازه بگیرید. همچنین می‌توانید کارایی استریم تصویری را با تست استریم پویا و سازگار تحت HTTP (DASH) اندازه بگیرید.

▶ Open data
OONI داده‌های سنجش شبکه را منتشر می‌کند زیرا داده‌های آزاد به طرفین ثالث اجازه می‌دهد تا یافته‌های OONI را تائید کنند، مطالعات مستقل انجام دهند و سایر سوالات تحقیق را پاسخ دهند. انتشار آزاد داده‌های OONI همچنین به شفافیت سانسور اینترنت در دنیا کمک می‌‌کند. شما می‌توانید داده‌های OONI را اینجا بارگیری کنید: https://ooni.io/data/

▶ Free software
تمامی تست‌های کاوشگر OONI (شامل NDT و DASH) بر اساس نرم افزار رایگان و متن باز بنا شده‌اند. شما می‌توانید پروژه‌ی نرم افزار OONI را در GitHub پیدا کنید: https://github.com/ooni. آیا کنجکاوید که در خصوص نحوه‌ی کار تست‌های کاوشگر OONI یاد بگیرید؟ بیشتر بخوانید: https://ooni.io/nettest/

برای دریافت بروز رسانی‌ از OONI، ما را در توییتر دنبال کنید: https://twitter.com/OpenObservatory', description_fa_source = 'official' WHERE package_name = 'org.openobservatory.ooniprobe' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Auxio یک پخش‌کننده موسیقی محلی با رابط کاربری/تجربه کاربری سریع و قابل اطمینان و بدون ویژگی‌های بی‌فایده موجود در سایر پخش‌کننده‌های موسیقی است. Auxio بر اساس کتابخانه‌های پخش رسانه مدرن ساخته شده است، به همین دلیل در مقایسه با سایر برنامه‌هایی که از قابلیت‌های قدیمی اندروید استفاده می‌کنند، از پشتیبانی کتابخانه‌ای و کیفیت شنیداری بهتری برخوردار است. خلاصه اینکه، <b>موسیقی پخش می‌کند.</b>

<b>ویژگی‌ها</b>

- پخش بر اساس Media3 ExoPlayer
- رابط کاربری سریع برگرفته از آخرین دستورالعمل‌های طراحی متریال
- تجربه کاربری با سلیقه که سهولت استفاده را بر موارد حاشیه‌ای اولویت می‌دهد
- رفتار قابل تنظیم
- پشتیبانی از شماره دیسک، چندین هنرمند برای یک موسیقی، انواع انتشار، تاریخ دقیق/اصلی، برچسب‌های مرتب‌سازی و موارد دیگر
- سیستم هنرمند پیشرفته که هنرمندان موسیقی و هنرمندان آلبوم را یکپارچه می‌کند
- مدیریت پوشه با توجه به کارت SD
- قابلیت پخش قابل اعتماد
- پایداری وضعیت پخش
- پشتیبانی خودکار اندروید
- پخش خودکار پیوسته
- پشتیبانی کامل از ReplayGain (در فایل‌های MP3، FLAC، OGG، OPUS و MP4)
- پشتیبانی از تنظیم کننده های شنیداری خارجی (مثلاً Wavelet)
- طراحی تمام صفحه
- پشتیبانی از جلد های تعبیه شده در فایل صوتی
- قابلیت جستجو
- پخش خودکار هدست
- ویجت‌های شیک که به طور خودکار با اندازه آنها سازگار می‌شوند
- کاملاً خصوصی و آفلاین
- بدون کاورهای آلبوم گرد (اگر آنها را میخواهید)', description_fa_source = 'official' WHERE package_name = 'org.oxycblt.auxio' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'پیکسل‌دروید، کارخواه اندرویدی آزاد و متن‌باز برای سکوی فدرالیزه هم‌رسانی تصویر پیکسل‌فد است.

بین نمایه‌ها و خوراک‌ها بچرخید، مطلب منتشر کنید، فرسته‌های دیگران را کاوش کنید و با دیگر افراد روی فدیورس تعامل داشته باشید.

• پشتیبانی از چند حساب
