UPDATE apps SET description_fa = '<b>I2P</b> (پروتکل اینترنت نامرئی) یک لایه جهانی و بی نام و نشان از شبکه است.
تمام ارتباطات بر روی I2P بی نام و نشان و سرتاسر رمزگذاری شده، مشترکین آدرس IP واقعی خود را آشکار نمیکنند.

<b>I2P client</b> یک نرم افزاری است که برای ساخت و تعامل با شبکه های بی نام و نشان I2P استفاده می شود.
این شبکه ها عموما برای ارتباطات بی نام و نشان همتا به همتا (اشتراک فایل، رمزارز) و ارتباطات بی نام و نشان کاربر و سرور (وبسایت ها، پیامرسان ها، سرور های گفت و گو) استفاده می شود.

<b>I2P</b> به همه مردم دنیا این امکان را میدهد که بدون محدودیت ارتباط برقرار کنند و اطلاعات به اشتراک بگذارند.

برای اطلاعات بیشتر در مورد <b>I2P</b>, میتوانید <a href="https://en.m.wikipedia.org/wiki/I2P">در ویکیپدیا مطالعه کنید</a>.', description_fa_source = 'official' WHERE package_name = 'org.purplei2p.i2pd' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'نیوپایپ از هیچ کتابخانه از چهارچوب گوگل یا API یوتیوب استفاده نمی‌کند. این برنامه تنها وب‌گاه را به منظور دریافت اطلاعات مورد نیاز تجزیه می‌کند. در نتیجه این برنامه، بدون نصب بودن خدمات گوکل نیز قابل استفاده است. همچنین برای استفاده از نیوپایپ، نیازی به حساب یوتیوب ندارید. آزاد نیز هست.', description_fa_source = 'official' WHERE package_name = 'org.schabi.newpipe' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'اپ اندروید رسمی ویکی‌پدیا برای کمک به یافتن، کشف و کاوش دانش در ویکی‌پدیا طراحی شده است. با یک جست‌وجوی سریع در برنامه با دوستانتان شرط بندی کنید، یا در قسمت مطالب برگزیده، تصویرها، مطالب پیشنهادی، غرق شوید. دانشنامه ی آزاد محبوبتان هم‌اکنون در نوک انگشتان شماست.

ویژگی‌ها:

خوراک کاوش - «خوراک کاوش» جدید، محتوای پیشنهادی و دائما در حال به‌روز رسانی ویکی‌پدیا را شامل جستارهای باب‌شده، رویدادهای کنونی، پیشنهاد خواندن و بیش‌تر، توصیه می‌کند.

جستجوی صوتی یکپارچه - به راحتی می تواند با نوار جستجوی برجسته در بالای اپلیکیشن به دنبال چیزی که می‌خواهید بگردید. از جمله جستجوی صوتی فعال در دستگاه شما.

نزدیک شما - در مورد چیزهای که در اطراف شما می‌گذرد با خبر شوبد با نقاط نقشه تعاملی برای دیدن مقاله‌هایی مربوط به مکان فعلی و نزدیک شما.

پشتیبانی زبان - بطور یکپارچه به هر زبانی که ویکی‌پدیا ساپورت می‌کند تغییر دهید٬ چه با عوض کردن زبان مقاله فعلی یا تغییر زبان جستجو در زمانی که جستجو می‌کنید.

پیش‌نمایش لینک - بر روی مقاله فشار دهید تا پیش‌نمایش آن را ببینید بدون آنکه از چیزی که در حال حاضر می‌خوانید خارج شوید. بر روی لینک فشار دهید و آن را نگه دارید تا یک زبانه جدید برای شما باز شود که به شما این امکان را می‌دهد که به خواندن مقاله‌ خود ادامه دهید و بعد از آن به لینک جدیدی که باز کرده بودید بروید.

جدول محتوا - به سمت چپ هر مقاله‌ای بکشید تا جدول محتوا را نمایان کند٬ چرا که به شما اجازه می‌دهد به راحتی به بخش مقاله‌ها بروید.

لیست خواندنی‌ها - شما می‌توانید مقاله‌هایی را که می‌خوانید همه در یک لیست قرار دهید و شما این امکان را خواهید داشت که حتی وقتی آفلاین هستید آن را بخوانید. هر چندتا لیست که می‌خواهید می‌توانید درست کنید و حتی برای آنها نام و توضیحات بگذارید و آنها را با مقالاتی از هر زبان ویکی آشنا کنید.

گالری تصاویر - بر روی عکس فشار دهید تا آن را بطور کامل با کیفیت خوب ببینید٬ به همراه گزینه های برای جابجا کردن بین عکس‌های دیگر.

تعاریف از فرهنگ لغت ویکی - بر روی کلمه فشار دهید تا آن را انتخاب کنید سپس بر روی دکمه Define فشار دهید تا تعریف آن کلمه را از فرهنگ لغت ویکی ببنید.

ویکی‌پدیا صفر - برای دسترسی به ویکی‌پدیا بدون هیچ هزینه‌ای ازاپراتور موبایل خود از این گزنیه استفاده کنید. (link to participating operators).

نظر خود را درباره اپلیکیشن برای ما بفرستید! در منو، "تنظیمات" را فشار دهید و سپس به قسمت "درباره ویکی‌پدیا اپلیکیشن بروید و سپس به قسمت "ارسال نظر درباره اپلیکیشن" بروید.

این کد بطور ۱۰۰٪ منبع باز است. اگر هر تجربه‌ای برای کار کردن با جاوا یا آندروید SDK دارید٬ ما حتما منتظر کمک‌های شما هستیم!‌ https://github.com/wikimedia/apps-android-wikipedia

با استفاده از این اپلیکیشن شما این اجازه را می‌دهید که بطور خودکار گزارشات خرابی به شخص ثالث ارائه دهنده سرویس ارسال شود. اگر علاقه دارید این امکان متوقف شود لطفا به "تنظیمات" بروید و سپس "ارسال گزارش خرابی" را خاموش کنید. توضیح مجوزهای مورد نیاز برنامه: https://www.mediawiki.org/wiki/Wikimedia_Apps/Android_FAQ#Security_and_Permissions

سیاست محرمانگی: https://m.wikimediafoundation.org/wiki/Privacy_policy

قوانین شخص ثالث ارائه دهنده سرویس برای گزارش خرابی‌ها : https://www.microsoft.com/en-us/privacystatement/OnlineServices/Default.aspx

شرایط استفاده: https://m.wikimediafoundation.org/wiki/Terms_of_Use

درباره بنیاد ویکی‌مدیا

بنیاد ویکی مدیا یک سازمان غیر انتفاعی محسوب می‌شود و به ویکی‌پدیا و دیگر‌ پروژهای ویکی‌مدیا کمک می‌کند. بنیاد ویکی‌مدیا یک سازمان خیریه است که به طور عمده از طریق کمک های مالی تامین می شود. برای اطلاعات بیشتر به وب‌سایت ما بروید: https://wikimediafoundation.org/wiki/Home.', description_fa_source = 'official' WHERE package_name = 'org.wikipedia' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'در دنیای ویدیوهای ویروسی و تشخیص چهره٬ ObscuraCam به شما کمک می‌کند تا عکس‌ها و فیلم‌های خود را با حفظ حریم شخصی به اشتراک بگذارید

حریم خصوصی عکس‌های شما: ObscuraCam می‌تواند به‌عنوان دوربین برای گرفتن عکس‌ها یا برای ناشناس‌کردن عکس‌ها و ویدئوهایی تا همین‌الان گرفته‌اید، استفاده شود.

تغییر خودتان: پوشاندن چهره با پیکسل، شطرنجی‌کردن یا گذاشتن یک بینی خنده‌دار و عینک.
تشخیص چهره‌ خودکار: ObscuraCam به‌طور خودکار می‌تواند در عکس‌ها و ویدئوها چهره را تشخیص دهد به‌طوری که شما می‌توانید سریع و به‌راحتی چهره‌های در یک جمعیت عظیم یا در یک ویدئوی طولانی را ناشناس کنید.
حالت‌های حفظ حریم خصوصی چندگانه: صورت‌ها می‌توانند پیکسلی شوند، کاملاً برداشته شوند یا با یک بینی بامزه و عینک مبدل شوند. شما هم‌چنین می‌توانید همه‌چیز را به‌جز یک بخش کوچک از یک تصویر محو کنید.
به‌اشتراک‌گذاری ایمن: ما تمام داده‌های شناساننده ذخیره‌شده در عکس را هم‌چون داده‌ مکان GPS، تلفن و مدل آن را برداریم به‌طور که شما می‌توانید عکس حفاظت‌شده‌ برگشتی را در گالری ذخیره کنید یا به‌طور مستقیم در فیسبوک، توییتر یا هر ابزار فعال دیگر اشتراک‌گذاری به اشتراک بگذارید.
حفاظت از هویت عکاس یک عکس: گوشی‌های هوشمند اطلاعات خود را به هر عکسی که با آن‌ها گرفته می‌شود، پیوست می‌کنند مانند محل گرفته‌شدن عکس و نوع دوربینی که با آن گرفته شده است. ObscuraCam تمام این اطلاعات را برمی‌دارد.
برنده جایزه: ObscuraCam برنده شوالیه چالش خبری در سال 2013 شد.

***بیشتر بدانید***

مشارکت: ObscuraCam مشارکتی میان متخصصان امنیت در پروژه پشتیبان و WITNESS.org (سازمانی غیرانتفاعی که با استفاده از قدرت تصویر و داستان‌گویی، چشمان جهان را بر نقض حقوق بشر می‌گشاید) است.
* وب سایت ما: https://GuardianProject.info
* درباره ویتنس: سازمانی غیرانتفاعی که با استفاده از قدرت تصویر و داستان‌گویی، چشمان جهان را بر نقض حقوق بشر می‌گشاید.
* شاهد وب سایت: http://witness.org
* در توییتر: https://twitter.com/guardianproject و https://twitter.com/witnessorg
نرم‌افزار آزاد: ObscuraCam نرم‌افزاری آزاد است. می‌توانید نگاهی به کدهای مبدأمان انداخته یا برای کمک به بهترشدن اوروب، به این مجموعه بپیوندید: https://github.com/guardianproject/ObscuraCam
* به ما پیام دهید: آیا ویژگی مورد علاقه‌تان را از قلم انداخته‌ایم؟ مشکل آزاردهنده‌ای یافتید؟ لطفاً به ما بگویید! ما عاشق شنیدن از شماییم. رایانامه‌ای بهمان بفرستید: support@guardianproject.info

تشخیص چهره، محو کردن، پیکسلی‌کردن، فعالیت حقوق بشری، orbot، tor، حریم خصوصی، محو منبع، تیره‌کردن، حریم خصوصی، دوربین، ویرایش عکس، روزنامه‌نگار، روزنامه‌نگاری، فوتوشاپ، ویدیو، پردازش ویدئو، موزاییک، ناشناس‌ماندن', description_fa_source = 'official' WHERE package_name = 'org.witness.sscphase1' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'SherpaTTS یک موتور تبدیل متن به گفتار اندروید است که بر اساس نسل بعدی Kaldi با استفاده از صدای Piper یا Coqui ساخته شده است.
پس از راه اندازی برنامه برای نخستین بار، مدل صدای دلخواه شما را از Hugging Face دانلود می کند. 
لطفا توجه داشته باشید که این تنها موردی است که مجوز اینترنت مورد نیاز است. 
پس از بارگیری مدل، تبدیل متن به گفتار کاملا آفلاین کار می کند و حریم خصوصی و راحتی شما را تضمین می کند.', description_fa_source = 'official' WHERE package_name = 'org.woheller69.ttsengine' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Whisper یک ویرایشگر روش ورودی (IME) با تشخیص صدا مبتنی بر Whisper است.

این برنامه می‌تواند به عنوان یک برنامه مستقل عمل کند و همچنین یک IME ارائه می‌دهد که می‌تواند به عنوان مثال از طریق دکمه میکروفون در <a href="https://f-droid.org/packages/helium314.keyboard/">HeliBoard</a> فعال شود.

در اولین اجرا، باید مدل‌های Whisper را از Hugging Face دانلود کنید.

این تنها استفاده از مجوز اینترنت است.

تشخیص صدا کاملاً آفلاین کار می‌کند.

Whisper به عنوان یک برنامه مستقل، می‌تواند هر زبان پشتیبانی شده را به انگلیسی ترجمه کند.

برای بهره‌مندی هرچه بیشتر از Whisper:

<ul>
<li>هنگام صحبت کردن دکمه را فشار داده و نگه دارید</li>
<li>قبل از شروع صحبت، کمی مکث کنید</li>
<li>با صدای بلند، واضح و با سرعت متوسط صحبت کنید</li>
<li>لطفاً توجه داشته باشید که برای هر ضبط محدودیت 30 ثانیه وجود دارد</li>
</ul>', description_fa_source = 'official' WHERE package_name = 'org.woheller69.whisper' AND description_fa IS NULL;
UPDATE apps SET description_fa = 'Translate text to Morse code or decipher Morse code by translating them to text! It’s a simple, user friendly, but useful app that can help you in a lot of ways. You can decipher or decode Morse codes, you can create secret number or learn to be a cipher or learn cryptography, and many more! If you think of yourself as a codebreaker, download and try our Morse code cypher tool! Don’t let the special characters or dots and dashes befuddle you. 

FEATURES OF MORSE CODE CIPHER TOOL:
•	Clean, modern app design and interface.
•	Super easy to use. 
•	Realtime translation: type in the word or code and we will translate it to you immediately.  
•	Decode from Morse to text or text to Morse.
•	Press the speaker button to hear the code in sound.
•	Copy the text by pressing copy button.
•	Type in dot and dash using our built-in Morse keyboard. 
•	Open Source (https://github.com/Crazy-Marvin/Morse)
•	More features coming up later! 
What is Morse code? Morse code is a system to encode letters and numbers to dash and dot signs. The duration of the dash is three times the duration of a dot. Each dot or dash is followed by period of signal absence, called a space, equal to the dot duration. Morse code was first used for communicating via telegraph. The most well-known Morse code is SOS, which is used to signal an emergency. Aside from typing dots and dash, you can also signal Morse code by turning light on and off, sounding a horn or tapping, and many more.  You can use Morse code to transmit messages easily via various means if the recipient understands Morse code. If they don’t, they can use our cipher tool to find out the password, secret number, or any info you want to relay. 
Since people rarely communicate via telegraph, nowadays there are very few people who can memorize Morse codes. Instead, it has become a way to encode something or special characters for special purposes. Of course, these special characters are still widely used in many situations, you don’t know when you are going to really need it. It’s a useful language to know even if you just want to learn cryptography or cryptogram for fun. 
How Morse is useful for you:
1.	Tell others when you are in a dangerous situation (SOS).
2.	Hide your secret number or password via dots and dashes. 
3.	Cipher/ Decipher hidden clues in games. 
4.	Learn cryptography or cryptogram through learning Morse codes. 
5.	Become a codebreaker by breaking secret codes in real time translation. 
6.	And many more! 

So, what are you waiting for? Use our Morse code cipher tool to decipher Morse code to text or text to Morse code now! As a codebreaker & cryptogram enthusiast, our cipher tool is a must have! It is useful for all of you. Just try it out.
---
We hope that you enjoy using our cipher tool to decode, to learn cryptography, or other purposes. If you do, please support our Morse decoder app by giving a rating and review on our Google Play store page and/or a star on GitHub. It will only take a minute and it will mean the world for us!
If you have problems in using Morse app, please write us an email or open an issue on GitHub. We will respond immediately and fix the bug as soon as we can.', description_fa_source = 'official' WHERE package_name = 'rocks.poopjournal.morse' AND description_fa IS NULL;
